/* Penny prototype screens, part 2: recurring, debt, people, groups, remittances, circles, insights, alerts, settings, security, data, profiles and spaces, history, trash, Plus, importer, notes. */
(function(PO){
const esc=PO.esc, $=PO.$, t=k=>PO.t(k), H=PO.H;

/* ---------- recurring, bills, subscriptions */
PO.SCREENS.recurring = { render:()=>{ PO.list('recur').forEach(PO.ensureOcc); const recs=PO.list('recur'); const occ=PO.list('occ').filter(o=>o.status==='upcoming').sort((a,b)=>a.date.localeCompare(b.date)).map(o=>({o,r:PO.get('recur',o.recId)})).filter(x=>x.r&&!x.r.deleted_at).slice(0,12); const subs=recs.filter(r=>r.subscription); const yearly=subs.reduce((s,r)=>s+PO.toBase(r.amt,r.cur)*(r.freq==='monthly'?12:r.freq==='weekly'?52:1),0); const p=PO.curPeriod(); const safe=PO.safeToSpend(p);
  const cal=(()=>{ const T=PO.today(); const {y,m}=PO.parseYmd(T); const L=PO.lastDay(y,m); const first=PO.weekday(PO.mk(y,m,1)); const ws=PO.profile().weekStart??1; const has=new Set(PO.list('occ').filter(o=>o.date.startsWith(T.slice(0,7))).map(o=>Number(o.date.slice(8)))); let cells=[]; const lead=(first-ws+7)%7; for(let i=0;i<lead;i++) cells.push(''); for(let d=1;d<=L;d++) cells.push(d); while(cells.length%7) cells.push(''); const rows=[]; for(let i=0;i<cells.length;i+=7) rows.push(cells.slice(i,i+7)); const names=['S','M','T','W','T','F','S']; return `<table class="caltable" aria-label="Bills this month"><tr>${Array.from({length:7},(_,i)=>`<th>${names[(ws+i)%7]}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td class="${c&&has.has(c)?'has':''}">${c||''}</td>`).join('')}</tr>`).join('')}</table>`; })();
  return `${H.hdr(t('recurring'), `${recs.length} items · subscriptions ${PO.fmt(yearly)} a year`, `<button class="pill acc" data-act="recur-add">+ New</button>`, t('home'))}
  <div class="card">${cal}</div>
  <div class="sec">Upcoming</div><div class="card list">${occ.length?occ.map(({o,r})=>{ const amt=PO.toBase(o.amt??r.amt,r.cur); const covered=r.kind==='income'||safe>=amt; return `<div class="row"><div style="min-width:0"><div class="t">${esc(r.name)} ${r.subscription?'<span class="pill">subscription</span>':''}${r.kind==='income'?'<span class="pill good">income</span>':''}${r.variable?'<span class="pill">estimate</span>':''}</div><div class="m">${esc(PO.relDate(o.date))} · ${esc(PO.acctName(r.acct))} · ${covered?'covered by safe to spend':`<span style="color:var(--amber)">short by ${PO.fmt(amt-safe)}</span>`}${r.note?' · '+esc(r.note):''}</div></div><div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end">${H.money((r.kind==='income'?1:-1)*amt,null,{signed:true,plus:true})}<button class="chip small" data-act="occ-pay" data-id="${o.id}">${r.kind==='income'?'Received':'Paid'}</button><button class="chip small" data-act="occ-skip" data-id="${o.id}">Skip</button><button class="chip small" data-act="occ-edit" data-id="${o.id}">${t('edit')}</button></div></div>`; }).join(''):H.empty('Nothing scheduled','Add rent, EMIs, subscriptions and salary so safe-to-spend can plan for them.')}</div>
  <div class="sec">All recurring</div><div class="card list">${recs.map(r=>`<div class="row"><div style="min-width:0"><div class="t">${esc(r.name)} ${r.paused?'<span class="pill">paused</span>':''}</div><div class="m">${esc(r.freq)} every ${r.interval||1} · ${esc(PO.fmt(r.amt,r.cur))}${r.autoPost?' · auto-post':''}${r.detected?' · detected from card':''}</div></div><div class="menu"><button class="chip small" data-act="recur-edit" data-id="${r.id}">${t('edit')}</button><button class="chip small" data-act="recur-pause" data-id="${r.id}">${r.paused?'Resume':'Pause'}</button></div></div>`).join('')}</div>
  <div class="sec">Skipped</div><div class="chips">${PO.list('occ').filter(o=>o.status==='skipped').slice(0,6).map(o=>`<button class="chip small" data-act="occ-unskip" data-id="${o.id}">↩ ${esc(PO.get('recur',o.recId)?.name||'')} ${esc(PO.relDate(o.date))}</button>`).join('')||'<span class="sub">None</span>'}</div>
  <div class="card" style="margin-top:12px"><div class="row"><div><div class="t">Find subscriptions I forgot</div><div class="m">Repeating payee and amount across all accounts. Free.</div></div><button class="btn sm ghost" data-act="recur-detect">Scan</button></div></div>`; } };
PO.recurForm = (r={}) => { const isNew=!r.id; PO.form({title:isNew?'New recurring item':r.name, values:{name:r.name||'', kind:r.kind||'expense', amt:r.amt??null, variable:!!r.variable, acct:r.acct||PO.profile().defaultAcct, cat:r.cat||'', freq:r.freq||'monthly', interval:r.interval||1, start:r.start||PO.today(), byDay:r.byDay||'', until:r.until||'', autoPost:!!r.autoPost, leadDays:r.leadDays??2, subscription:!!r.subscription, note:r.note||''}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'kind',label:'Type',type:'chips',options:[{v:'expense',l:t('expense')},{v:'income',l:t('income')}]},{k:'amt',label:t('amount'),type:'money',required:true},{k:'variable',label:'Variable amount (estimate from last 6)',type:'toggle'},{k:'acct',label:t('account'),type:'select',options:H.acctOptions()},{k:'cat',label:t('category'),type:'select',options:[...H.catOptions('expense'),...H.catOptions('income')]},{k:'freq',label:'Repeats',type:'select',options:[{v:'daily',l:'Daily'},{v:'weekly',l:'Weekly'},{v:'monthly',l:'Monthly'},{v:'yearly',l:'Yearly'}]},{k:'interval',label:'Every N',type:'number',min:1},{k:'start',label:'First date',type:'date'},{k:'byDay',label:'Day of month (number or "last")',type:'text'},{k:'until',label:'Ends (optional)',type:'date'},{k:'leadDays',label:'Remind days before',type:'number',min:0},{k:'autoPost',label:'Post automatically on the day',type:'toggle'},{k:'subscription',label:'This is a subscription',type:'toggle'},{k:'note',label:t('note'),type:'text'}], onSave:v=>{ const gid=PO.group(()=>{ const id=r.id||PO.uid('rc'); PO.commit('recur',id,{name:v.name,kind:v.kind,amt:v.amt,cur:PO.cur(),variable:v.variable,acct:v.acct,cat:v.cat,freq:v.freq,interval:v.interval||1,start:v.start,byDay:v.byDay==='last'?'last':(Number(v.byDay)||null),until:v.until||null,leadDays:v.leadDays,autoPost:v.autoPost,subscription:v.subscription,note:v.note,paused:r.paused||false}); if(!isNew) PO.list('occ').filter(o=>o.recId===id&&o.status==='upcoming').forEach(o=>PO.purge('occ',o.id)); }); PO.list('recur').forEach(PO.ensureOcc); H.afterWrite('Saved. Upcoming occurrences regenerated.', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>{ PO.remove('recur',r.id); PO.list('occ').filter(o=>o.recId===r.id&&o.status==='upcoming').forEach(o=>PO.remove('occ',o.id)); }); H.afterWrite('Deleted', gid); } }); };
PO.ACT['recur-add'] = () => PO.recurForm();
PO.ACT['recur-edit'] = b => PO.recurForm(PO.get('recur',b.dataset.id));
PO.ACT['recur-pause'] = b => { const r=PO.get('recur',b.dataset.id); PO.commit('recur',r.id,{paused:!r.paused},'pause'); PO.render(); };
PO.ACT['occ-pay'] = b => { const o=PO.get('occ',b.dataset.id); const r=PO.get('recur',o.recId); const amt=o.amt??r.amt; const gid=PO.group(()=>{ const tid=PO.uid('t'); PO.commit('tx',tid,{kind:r.kind==='income'?'income':'expense',amt,cur:r.cur,acct:r.acct,cat:r.cat,payee:r.name,payeeId:PO.ensurePayee(r.name),date:PO.today(),status:'cleared',source:'recurring',recId:r.id,tags:[],splits:[],attachments:[]},'create'); PO.commit('occ',o.id,{status:'paid',txId:tid},'paid'); }); PO.ensureOcc(r); H.afterWrite(`${r.name} ${r.kind==='income'?'received':'paid'}. Next one scheduled.`, gid); };
PO.ACT['occ-skip'] = b => { const o=PO.get('occ',b.dataset.id); const gid=PO.group(()=>PO.commit('occ',o.id,{status:'skipped'},'skip')); PO.ensureOcc(PO.get('recur',o.recId)); H.afterWrite('Skipped this occurrence', gid); };
PO.ACT['occ-unskip'] = b => { PO.commit('occ',b.dataset.id,{status:'upcoming'},'unskip'); PO.render(); };
PO.ACT['occ-edit'] = b => { const o=PO.get('occ',b.dataset.id); const r=PO.get('recur',o.recId); PO.form({title:`${r.name} · ${PO.relDate(o.date)}`, values:{amt:o.amt??r.amt, date:o.date, scope:'this'}, fields:[{k:'scope',label:'Apply to',type:'chips',options:[{v:'this',l:'This occurrence only'},{v:'future',l:'This and all future'}]},{k:'amt',label:t('amount'),type:'money',required:true},{k:'date',label:t('date'),type:'date'}], onSave:v=>{ const gid=PO.group(()=>{ if(v.scope==='this') PO.commit('occ',o.id,{amt:v.amt,date:v.date},'edit'); else { PO.commit('recur',r.id,{amt:v.amt,start:v.date,byDay:r.freq==='monthly'?Number(v.date.slice(8)):r.byDay},'edit'); PO.list('occ').filter(x=>x.recId===r.id&&x.status==='upcoming').forEach(x=>PO.purge('occ',x.id)); PO.ensureOcc(PO.get('recur',r.id)); } }); H.afterWrite(v.scope==='this'?'This occurrence changed':'This and future occurrences changed', gid); } }); };
PO.ACT['recur-detect'] = () => { const by={}; PO.list('tx').filter(x=>x.kind==='expense').forEach(x=>{ const k=`${PO.payeeName(x)}|${x.amt}`; (by[k]=by[k]||[]).push(x); }); const found=Object.entries(by).filter(([k,v])=>v.length>=2&&k.split('|')[0]).filter(([k])=>!PO.list('recur').find(r=>r.name===k.split('|')[0])); if(!found.length){ PO.toast('No new repeating payments found'); return; } const gid=PO.group(()=>found.slice(0,3).forEach(([k,v])=>{ const x=v[0]; PO.commit('recur',PO.uid('rc'),{name:PO.payeeName(x),kind:'expense',amt:x.amt,cur:x.cur,acct:x.acct,cat:x.cat,freq:'monthly',interval:1,start:PO.addMonths(v.map(z=>z.date).sort().pop(),1),subscription:true,detected:true,leadDays:2}); })); PO.list('recur').forEach(PO.ensureOcc); H.afterWrite(`${Math.min(3,found.length)} subscriptions detected`, gid); };

/* ---------- debt planner */
PO.SCREENS.debt = { render:(pr)=>{ const debts=PO.list('accts').filter(a=>!a.archived&&(a.type==='card'||a.type==='loan'||a.type==='liability')&&PO.balance(a.id)<0).map(a=>({a,bal:-PO.balance(a.id),apr:a.apr||(a.type==='card'?36:12)})); const strat=pr.strat||'avalanche'; const extra=Number(pr.extra||0); const order=[...debts].sort((x,y)=>strat==='avalanche'?y.apr-x.apr:x.bal-y.bal); const sim=()=>{ let bals=order.map(d=>({...d,b:PO.toBase(d.bal,d.a.cur)})); const minPay=d=>Math.max(Math.round(d.b*0.03), PO.toMinor(500*(PO.RATES[PO.cur()]/84),PO.cur())); let m=0, interest=0; const ex=PO.toMinor(extra,PO.cur()); while(bals.some(d=>d.b>0)&&m<360){ m++; let pool=ex; bals.forEach(d=>{ if(d.b<=0) return; const i=Math.round(d.b*d.apr/1200); interest+=i; d.b+=i; const pay=Math.min(d.b,minPay(d)); d.b-=pay; }); for(const d of bals){ if(pool<=0) break; if(d.b<=0) continue; const pay=Math.min(d.b,pool); d.b-=pay; pool-=pay; } } return {m,interest}; }; const r=sim();
  return `${H.hdr('Debt planner', `${debts.length} debts · ${PO.fmt(debts.reduce((s,d)=>s+PO.toBase(d.bal,d.a.cur),0))} owed`, '', t('home'))}<div class="chips" style="margin-bottom:8px"><button class="chip small" data-go="debt" ${H.p({...pr,strat:'avalanche'})} aria-pressed="${strat==='avalanche'}">Avalanche (highest rate first)</button><button class="chip small" data-go="debt" ${H.p({...pr,strat:'snowball'})} aria-pressed="${strat==='snowball'}">Snowball (smallest first)</button><button class="chip small" data-act="debt-extra" ${H.p(pr)}>Extra per month: ${esc(PO.fmt(PO.toMinor(extra,PO.cur())))}</button></div><div class="card"><b>Debt-free in ${r.m} months</b><div class="sub">Total interest about ${PO.fmt(r.interest)} with minimum payments${extra?` plus ${PO.fmt(PO.toMinor(extra,PO.cur()))} extra`:''}. Plain words: every ${PO.fmt(PO.toMinor(1000,PO.cur()))} extra per month shortens this noticeably; try it.</div></div><div class="card list">${order.map((d,i)=>`<div class="row" role="button" tabindex="0" data-go="account" ${H.p({id:d.a.id})}><div><div class="t">${i+1}. ${esc(d.a.name)}</div><div class="m">${d.apr}% a year · ${d.a.type}</div></div>${H.money(-d.bal,d.a.cur)}</div>`).join('')||H.empty('No debts','Cards, loans and pay-later balances appear here.')}</div>`; } };
PO.ACT['debt-extra'] = b => { const pr=JSON.parse(b.dataset.p||'{}'); PO.form({title:'Extra per month', values:{amt:PO.toMinor(Number(pr.extra||0),PO.cur())}, fields:[{k:'amt',label:t('amount'),type:'money',autofocus:true}], onSave:v=>PO.go('debt',{...pr,extra:PO.toMajor(v.amt||0,PO.cur())}) }); };

/* ---------- people: lending, groups, remittances, circles */
PO.SCREENS.people = { render:()=>{ const lends=PO.list('lend'); const rec=lends.filter(l=>l.dir==='receive').reduce((s,l)=>s+l.amt-(l.settled||0),0), give=lends.filter(l=>l.dir==='give').reduce((s,l)=>s+l.amt-(l.settled||0),0); const groups=PO.list('groups'); const prof=PO.profile();
  return `${H.hdr(t('people'), prof.kind==='space'?`${t('space')} · ${(prof.members||[]).length} ${t('members').toLowerCase()}`:'Lending, groups, remittances and circles', `<button class="pill acc" data-go="profiles">${t('profiles')}</button>`)}
  <div class="sec">${t('lending')} <button class="pill" data-act="lend-add" style="float:inline-end">+ Entry</button></div><div class="card"><div class="grid2" style="margin-bottom:6px"><div><div class="sub">To receive</div><div class="amt in">${esc(PO.fmt(rec))}</div></div><div><div class="sub">To give</div><div class="amt">${esc(PO.fmt(give))}</div></div></div><div class="list">${lends.map(l=>`<div class="row" role="button" tabindex="0" data-go="person" ${H.p({id:l.id})}><div style="min-width:0"><div class="t">${esc(PO.personName(l.personId))}</div><div class="m">${esc(l.note||'')} · ${esc(PO.relDate(l.date))}${l.due?` · ${PO.fmtDate(l.due)}`:''}${l.interest?` · ${l.interest}% simple`:''}</div></div>${H.money((l.dir==='receive'?1:-1)*(l.amt-(l.settled||0)),null,{signed:true})}</div>`).join('')||H.empty('No lending yet','Money you gave or borrowed, with gentle reminders you send yourself.')}</div></div>
  <div class="sec">${t('groups')} <button class="pill" data-act="group-add" style="float:inline-end">+ Group</button></div>${groups.map(g=>{ const bal=PO.groupBalances(g); const mine=bal[PO.state.login.id]||0; return `<button class="card" style="width:100%;text-align:start" data-go="group" ${H.p({id:g.id})}><div style="display:flex;justify-content:space-between;align-items:center"><div><b>${esc(g.name)}</b><div class="sub">${g.members.length} members · ${PO.list('gexp').filter(e=>e.groupId===g.id).length} expenses</div></div>${H.money(mine,g.cur,{signed:true,plus:true})}</div></button>`; }).join('')||`<div class="card">${H.empty('No groups','Split trips, flats and dinners; friends without the app get a web link.')}</div>`}
  <div class="sec">${t('remittance')} <button class="pill" data-act="remit-add" style="float:inline-end">+ Record</button></div><div class="card list">${PO.list('remit').map(r=>{ const mid=PO.RATES[r.gotCur]/PO.RATES[r.sentCur]; const spread=mid?Math.max(0,(mid-r.rate)/mid*100):0; const feePct=r.fee/r.sentAmt*100; return `<div class="row" role="button" tabindex="0" data-act="remit-edit" data-id="${r.id}"><div style="min-width:0"><div class="t">${esc(r.from)}, ${esc(r.fromPlace)}</div><div class="m">${esc(PO.fmt(r.sentAmt,r.sentCur,{force:true}))} sent · fee ${esc(PO.fmt(r.fee,r.sentCur,{force:true}))} · 1 ${r.sentCur} = ${r.rate} · true cost ${(feePct+spread).toFixed(1)}% · ${esc(r.purpose)}</div></div>${H.money(r.gotAmt,r.gotCur,{signed:true,plus:true})}</div>`; }).join('')||H.empty('No remittances','Sent, fee, rate and received as one record, visible to both sides.')}</div>
  <div class="sec">${t('circles')} <button class="pill" data-act="circle-add" style="float:inline-end">+ Circle</button></div>${PO.list('circles').map(c=>`<button class="card" style="width:100%;text-align:start" data-go="circle" ${H.p({id:c.id})}><div style="display:flex;justify-content:space-between;align-items:center"><div><b>${esc(c.name)}</b><div class="sub">${c.members} members · ${PO.fmt(c.contrib)} ${esc(c.every)} · round ${c.turn} of ${c.members}</div></div><span class="pill acc">your turn ${c.myTurn}</span></div></button>`).join('')||`<div class="card">${H.empty('No circles',`${PO.pack().circles.join(', ')}: rotating savings with turn order.`)}</div>`}`; } };
PO.lendForm = (l={}) => { const isNew=!l.id; const people=PO.list('people'); PO.form({title:isNew?'New lending entry':`${t('edit')} · ${PO.personName(l.personId)}`, values:{who:l.personId?PO.personName(l.personId):'', dir:l.dir||'receive', amt:l.amt??null, date:l.date||PO.today(), due:l.due||'', interest:l.interest||0, note:l.note||'', acct:l.acct||PO.profile().defaultAcct, post:isNew}, fields:[{k:'who',label:'Person',type:'text',required:true,datalist:people.map(p=>p.name),autofocus:true},{k:'dir',label:'Direction',type:'chips',options:[{v:'receive',l:'I gave (to receive)'},{v:'give',l:'I borrowed (to give)'}]},{k:'amt',label:t('amount'),type:'money',required:true},{k:'date',label:t('date'),type:'date'},{k:'due',label:'Due (optional)',type:'date'},{k:'interest',label:'Simple interest % per year',type:'number',min:0},{k:'note',label:t('note'),type:'text'},{k:'acct',label:'Account the money moved through',type:'select',options:H.acctOptions()},{k:'post',label:'Also post the transaction in my book',type:'toggle',hidden:()=>!isNew}], onSave:v=>{ let person=people.find(p=>p.name.toLowerCase()===v.who.trim().toLowerCase()); const gid=PO.group(()=>{ if(!person) person=PO.commit('people',PO.uid('pp'),{name:v.who.trim()}); const id=l.id||PO.uid('ld'); PO.commit('lend',id,{personId:person.id,dir:v.dir,amt:v.amt,date:v.date,due:v.due||null,interest:v.interest||0,note:v.note,acct:v.acct,settled:l.settled||0,entries:l.entries||[{date:v.date,amt:v.amt,type:v.dir==='receive'?'gave':'got'}]}); if(v.post&&isNew) PO.commit('tx',PO.uid('t'),{kind:v.dir==='receive'?'expense':'income',amt:v.amt,cur:PO.cur(),acct:v.acct,cat:PO.cid(PO.state.currentProfile,v.dir==='receive'?'loan.given':'inc.other'),payee:person.name,payeeId:PO.ensurePayee(person.name),date:v.date,status:'cleared',source:'lending',lendId:id,tags:[],splits:[],attachments:[]},'create'); }); H.afterWrite('Saved', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>PO.remove('lend',l.id)); PO.go('people'); PO.toast('Deleted', gid); } }); };
PO.ACT['lend-add'] = () => PO.lendForm();
PO.SCREENS.person = { render:(pr)=>{ const l=PO.get('lend',pr.id); if(!l) return H.err('Entry not found','',''); const open=l.amt-(l.settled||0); const days=PO.daysBetween(l.date,PO.today()); const interest=l.interest?Math.round(open*l.interest/100*days/365):0; const msg = l.dir==='receive' ? `Hi ${PO.personName(l.personId)}, a gentle reminder about the ${PO.fmt(open,null,{force:true})} from ${PO.fmtDate(l.date)}. No rush, just keeping track.` : `Hi ${PO.personName(l.personId)}, I will settle the ${PO.fmt(open,null,{force:true})} ${l.due?'by '+PO.fmtDate(l.due):'soon'}. Thank you!`;
  return `${H.hdr(PO.personName(l.personId), l.dir==='receive'?'To receive':'To give', `<button class="pill" data-act="lend-edit" data-id="${l.id}">${t('edit')}</button>`, t('people'))}<div class="card"><div class="amtbox" style="text-align:start;padding:0;font-size:30px">${esc(PO.fmt(open))}</div><div class="sub">${esc(l.note||'')} · since ${esc(PO.fmtDate(l.date))}${l.due?` · due ${esc(PO.fmtDate(l.due))}`:''}${interest?` · interest so far ${PO.fmt(interest)} (${l.interest}% simple)`:''}</div><div class="menu" style="margin-top:8px"><button class="chip small" data-act="lend-entry" data-id="${l.id}">Record partial ${l.dir==='receive'?'repayment':'payment'}</button><button class="chip small" data-act="lend-settle" data-id="${l.id}">Settle in full</button><button class="chip small" data-act="lend-remind" data-id="${l.id}" data-msg="${esc(msg)}">Copy reminder</button></div></div><div class="sec">Timeline</div><div class="card list">${(l.entries||[]).slice().reverse().map(e=>`<div class="row"><div><div class="t">${e.type==='gave'?'Gave':e.type==='got'?'Received':e.type}</div><div class="m">${esc(PO.relDate(e.date))}</div></div>${H.money(e.amt)}</div>`).join('')}</div><div class="card"><b>Draft reminder</b><p class="sub" style="margin:6px 0 0">${esc(msg)}</p></div>`; } };
PO.ACT['lend-edit'] = b => PO.lendForm(PO.get('lend',b.dataset.id));
PO.ACT['lend-entry'] = b => { const l=PO.get('lend',b.dataset.id); const open=l.amt-(l.settled||0); PO.form({title:'Partial settlement', values:{amt:null,date:PO.today(),acct:l.acct||PO.profile().defaultAcct}, fields:[{k:'amt',label:`${t('amount')} (open ${PO.fmt(open,null,{force:true})})`,type:'money',required:true,autofocus:true},{k:'date',label:t('date'),type:'date'},{k:'acct',label:t('account'),type:'select',options:H.acctOptions()}], validate:v=>v.amt>open?{amt:'More than the open balance'}:null, onSave:v=>{ const gid=PO.group(()=>{ PO.commit('lend',l.id,{settled:(l.settled||0)+v.amt,entries:[...(l.entries||[]),{date:v.date,amt:v.amt,type:l.dir==='receive'?'got':'gave'}]},'settle'); PO.commit('tx',PO.uid('t'),{kind:l.dir==='receive'?'income':'expense',amt:v.amt,cur:PO.cur(),acct:v.acct,cat:PO.cid(PO.state.currentProfile,l.dir==='receive'?'inc.other':'loan.repay'),payee:PO.personName(l.personId),payeeId:PO.ensurePayee(PO.personName(l.personId)),date:v.date,status:'cleared',source:'lending',lendId:l.id,tags:[],splits:[],attachments:[]},'create'); }); H.afterWrite('Recorded', gid); } }); };
PO.ACT['lend-settle'] = b => { const l=PO.get('lend',b.dataset.id); const open=l.amt-(l.settled||0); const gid=PO.group(()=>{ PO.commit('lend',l.id,{settled:l.amt,entries:[...(l.entries||[]),{date:PO.today(),amt:open,type:l.dir==='receive'?'got':'gave'}],closed:true},'settle'); PO.commit('tx',PO.uid('t'),{kind:l.dir==='receive'?'income':'expense',amt:open,cur:PO.cur(),acct:l.acct||PO.profile().defaultAcct,cat:PO.cid(PO.state.currentProfile,l.dir==='receive'?'inc.other':'loan.repay'),payee:PO.personName(l.personId),payeeId:PO.ensurePayee(PO.personName(l.personId)),date:PO.today(),status:'cleared',source:'lending',lendId:l.id,tags:[],splits:[],attachments:[]},'create'); }); PO.go('people'); PO.toast('Settled', gid); };
PO.ACT['lend-remind'] = b => { const msg=b.dataset.msg; const done=()=>PO.toast('Copied. Paste it into WhatsApp or Messenger. The app never contacts anyone.'); if(navigator.clipboard&&navigator.clipboard.writeText) navigator.clipboard.writeText(msg).then(done).catch(()=>PO.toast('Select the draft text to copy it')); else PO.toast('Select the draft text to copy it'); };
PO.groupBalances = g => { const bal={}; g.members.forEach(m=>bal[m.id]=0); PO.list('gexp').filter(e=>e.groupId===g.id).forEach(e=>{ bal[e.payer]=(bal[e.payer]||0)+e.amt; e.shares.forEach(s=>{ bal[s.id]=(bal[s.id]||0)-s.amt; }); }); (g.settlements||[]).forEach(s=>{ bal[s.from]+=s.amt; bal[s.to]-=s.amt; }); return bal; };
PO.simplify = bal => { const debtors=Object.entries(bal).filter(([,v])=>v<0).map(([id,v])=>({id,v:-v})).sort((a,b)=>b.v-a.v); const creditors=Object.entries(bal).filter(([,v])=>v>0).map(([id,v])=>({id,v})).sort((a,b)=>b.v-a.v); const out=[]; let i=0,j=0; while(i<debtors.length&&j<creditors.length){ const x=Math.min(debtors[i].v,creditors[j].v); if(x>0) out.push({from:debtors[i].id,to:creditors[j].id,amt:x}); debtors[i].v-=x; creditors[j].v-=x; if(debtors[i].v<=0) i++; if(creditors[j].v<=0) j++; } return out; };
PO.SCREENS.group = { render:(pr)=>{ const g=PO.get('groups',pr.id); if(!g) return H.err('Group not found','',''); const name=id=>(g.members.find(m=>m.id===id)||{}).name||'?'; const bal=PO.groupBalances(g); const plan=PO.simplify(bal); const exps=PO.list('gexp').filter(e=>e.groupId===g.id).sort((a,b)=>b.date.localeCompare(a.date));
  return `${H.hdr(g.name, `${g.members.map(m=>m.name).join(', ')}`, `<div style="display:flex;gap:6px"><button class="pill" data-act="group-member" data-id="${g.id}">+ Member</button><button class="pill acc" data-act="gexp-add" data-id="${g.id}">+ Expense</button></div>`, t('people'))}<div class="card"><b>Balances</b>${g.members.map(m=>`<div class="row"><div class="t">${esc(m.name)} ${m.external?'<span class="pill">web link</span>':''}</div>${H.money(bal[m.id]||0,g.cur,{signed:true,plus:true})}</div>`).join('')}</div><div class="card"><b>Settle up (simplified)</b>${plan.length?plan.map(s=>`<div class="row"><div class="t">${esc(name(s.from))} → ${esc(name(s.to))}</div><div style="display:flex;gap:6px;align-items:center">${H.money(s.amt,g.cur)}<button class="chip small" data-act="group-settle" data-id="${g.id}" data-from="${s.from}" data-to="${s.to}" data-amt="${s.amt}">${PO.pack().settle[0]} · paid</button></div></div>`).join(''):'<div class="sub">All square.</div>'}</div><div class="sec">Expenses</div><div class="card list">${exps.map(e=>`<div class="row" role="button" tabindex="0" data-act="gexp-edit" data-id="${e.id}"><div style="min-width:0"><div class="t">${esc(e.desc)}</div><div class="m">${esc(name(e.payer))} paid · ${esc(PO.relDate(e.date))} · ${e.shares.map(s=>`${name(s.id)} ${PO.fmt(s.amt,g.cur,{force:true,noSym:true})}`).join(', ')}</div></div>${H.money(e.amt,g.cur)}</div>`).join('')||H.empty('No expenses yet','')}</div>`; } };
PO.ACT['group-add'] = () => PO.form({title:'New group', values:{cur:PO.cur()}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'cur',label:t('currency'),type:'select',options:Object.keys(PO.CUR).map(c=>({v:c,l:c}))},{k:'members',label:'Members (comma separated; emails invite non-users)',type:'text',placeholder:'Meera, ravi@example.com'}], onSave:v=>{ const members=[{id:PO.state.login.id,name:'You'},...v.members.split(',').map(s=>s.trim()).filter(Boolean).map(n=>({id:PO.uid('gm'),name:n,external:true}))]; const g=PO.commit('groups',PO.uid('gr'),{name:v.name,cur:v.cur,members,settlements:[]}); PO.go('group',{id:g.id}); }});
PO.ACT['group-member'] = b => { const g=PO.get('groups',b.dataset.id); PO.form({title:'Add member', fields:[{k:'name',label:'Name or email',type:'text',required:true,autofocus:true}], onSave:v=>{ PO.commit('groups',g.id,{members:[...g.members,{id:PO.uid('gm'),name:v.name.trim(),external:true}]},'member'); PO.render(); } }); };
PO.gexpForm = (g, e={}) => { const isNew=!e.id; PO.form({title:isNew?'Group expense':e.desc, values:{desc:e.desc||'', amt:e.amt??null, payer:e.payer||PO.state.login.id, date:e.date||PO.today(), mode:'equal', among:e.shares?e.shares.map(s=>s.id):g.members.map(m=>m.id)}, fields:[{k:'desc',label:'What',type:'text',required:true,autofocus:true},{k:'amt',label:t('amount'),type:'money',cur:g.cur,required:true},{k:'payer',label:'Paid by',type:'select',options:g.members.map(m=>({v:m.id,l:m.name}))},{k:'date',label:t('date'),type:'date'},{k:'among',label:'Split equally among',type:'chips',multi:true,options:g.members.map(m=>({v:m.id,l:m.name})),required:true}], onSave:v=>{ const n=v.among.length; const base=Math.floor(v.amt/n); const shares=v.among.map((id,i)=>({id,amt:base+(i<v.amt-base*n?1:0)})); const gid=PO.group(()=>PO.commit('gexp',e.id||PO.uid('ge'),{groupId:g.id,desc:v.desc,amt:v.amt,payer:v.payer,date:v.date,shares})); H.afterWrite('Saved', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>PO.remove('gexp',e.id)); H.afterWrite('Deleted', gid); } }); };
PO.ACT['gexp-add'] = b => PO.gexpForm(PO.get('groups',b.dataset.id));
PO.ACT['gexp-edit'] = b => { const e=PO.get('gexp',b.dataset.id); PO.gexpForm(PO.get('groups',e.groupId), e); };
PO.ACT['group-settle'] = b => { const g=PO.get('groups',b.dataset.id); const amt=Number(b.dataset.amt); const gid=PO.group(()=>{ PO.commit('groups',g.id,{settlements:[...(g.settlements||[]),{from:b.dataset.from,to:b.dataset.to,amt,date:PO.today()}]},'settle'); if(b.dataset.from===PO.state.login.id||b.dataset.to===PO.state.login.id){ const mine=b.dataset.from===PO.state.login.id; PO.commit('tx',PO.uid('t'),{kind:mine?'expense':'income',amt,cur:g.cur,acct:PO.profile().defaultAcct||(PO.list('accts')[0]||{}).id,cat:PO.cid(PO.state.currentProfile,mine?'loan.repay':'inc.other'),payee:g.name,payeeId:PO.ensurePayee(g.name),date:PO.today(),status:'cleared',source:'group',tags:[],splits:[],attachments:[]},'create'); } }); H.afterWrite('Settled and posted to your book', gid); };
PO.remitForm = (r={}) => { const isNew=!r.id; PO.form({title:isNew?'Record remittance':`${r.from}, ${r.fromPlace}`, values:{from:r.from||'', place:r.fromPlace||'', sentAmt:r.sentAmt??null, sentCur:r.sentCur||'AED', fee:r.fee??0, rate:r.rate||'', gotAmt:r.gotAmt??null, purpose:r.purpose||'Household', date:r.date||PO.today(), status:r.status||'received', acct:r.acct||PO.profile().defaultAcct, post:isNew}, fields:[{k:'from',label:'Sender',type:'text',required:true,autofocus:true},{k:'place',label:'From where',type:'text'},{k:'sentCur',label:'Sent currency',type:'select',options:Object.keys(PO.CUR).map(c=>({v:c,l:c}))},{k:'sentAmt',label:'Sent amount',type:'money',cur:r.sentCur||'AED',required:true},{k:'fee',label:'Fee (sent currency)',type:'money',cur:r.sentCur||'AED'},{k:'rate',label:`Rate: 1 sent currency = ? ${PO.cur()}`,type:'number'},{k:'gotAmt',label:`Received (${PO.cur()})`,type:'money',required:true},{k:'purpose',label:'Purpose',type:'text'},{k:'date',label:t('date'),type:'date'},{k:'status',label:t('status'),type:'chips',options:[{v:'sent',l:'Sent'},{v:'received',l:'Received'},{v:'confirmed',l:'Confirmed by both'}]},{k:'acct',label:'Received into',type:'select',options:H.acctOptions()},{k:'post',label:'Post as income in my book',type:'toggle',hidden:()=>!isNew}], onSave:v=>{ const gid=PO.group(()=>{ const id=r.id||PO.uid('rm'); PO.commit('remit',id,{from:v.from,fromPlace:v.place,sentAmt:v.sentAmt,sentCur:v.sentCur,fee:v.fee||0,rate:Number(v.rate)||0,gotAmt:v.gotAmt,gotCur:PO.cur(),purpose:v.purpose,date:v.date,status:v.status,acct:v.acct}); if(v.post&&isNew) PO.commit('tx',PO.uid('t'),{kind:'income',amt:v.gotAmt,cur:PO.cur(),acct:v.acct,cat:PO.cid(PO.state.currentProfile,'inc.remit'),payee:v.from,payeeId:PO.ensurePayee(v.from),date:v.date,status:'cleared',source:'remittance',remitId:id,tags:[],splits:[],attachments:[]},'create'); }); H.afterWrite('Recorded. It seeds this period\'s income.', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>PO.remove('remit',r.id)); H.afterWrite('Deleted', gid); } }); };
PO.ACT['remit-add'] = () => PO.remitForm();
PO.ACT['remit-edit'] = b => PO.remitForm(PO.get('remit',b.dataset.id));
PO.circleForm = (c={}) => { const isNew=!c.id; PO.form({title:isNew?`New circle (${PO.pack().circles.join(' / ')})`:c.name, values:{name:c.name||PO.pack().circles[0], members:c.members||10, contrib:c.contrib??null, every:c.every||'monthly', myTurn:c.myTurn||1, turn:c.turn||1, start:c.start||PO.today(), order:(c.order||[]).join(', ')}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'members',label:'Members',type:'number',min:2,required:true},{k:'contrib',label:'Contribution each round',type:'money',required:true},{k:'every',label:'Round frequency',type:'select',options:[{v:'weekly',l:'Weekly'},{v:'monthly',l:'Monthly'}]},{k:'turn',label:'Current round',type:'number',min:1},{k:'myTurn',label:'Your payout round',type:'number',min:1},{k:'start',label:'Started',type:'date'},{k:'order',label:'Turn order (names, comma separated)',type:'text'}], onSave:v=>{ const gid=PO.group(()=>PO.commit('circles',c.id||PO.uid('ci'),{name:v.name,members:v.members,contrib:v.contrib,every:v.every,turn:v.turn,myTurn:v.myTurn,start:v.start,order:v.order.split(',').map(s=>s.trim()).filter(Boolean)})); H.afterWrite('Saved', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>PO.remove('circles',c.id)); PO.go('people'); PO.toast('Deleted', gid); } }); };
PO.ACT['circle-add'] = () => PO.circleForm();
PO.SCREENS.circle = { render:(pr)=>{ const c=PO.get('circles',pr.id); if(!c) return H.err('Circle not found','',''); const pot=c.contrib*c.members; const paid=PO.list('contrib').filter(x=>x.circleId===c.id).sort((a,b)=>b.date.localeCompare(a.date)); const next=c.every==='weekly'?PO.addDays(c.start,7*c.turn):PO.addMonths(c.start,c.turn); const payoutDate=c.every==='weekly'?PO.addDays(c.start,7*(c.myTurn-1)):PO.addMonths(c.start,c.myTurn-1);
  return `${H.hdr(c.name, `${c.members} members · ${PO.fmt(c.contrib)} ${c.every}`, `<button class="pill" data-act="circle-edit" data-id="${c.id}">${t('edit')}</button>`, t('people'))}<div class="card"><div class="sub">Pot each round</div><div class="amtbox" style="text-align:start;padding:0;font-size:30px">${esc(PO.fmt(pot))}</div><div class="row"><div><div class="t">Your payout: round ${c.myTurn}</div><div class="m">${esc(PO.fmtDate(payoutDate,{day:'numeric',month:'short',year:'numeric'}))} · fills itself as a goal</div></div><span class="pill ${c.turn>=c.myTurn?'good':'acc'}">${c.turn>=c.myTurn?'paid out':'upcoming'}</span></div><div class="row"><div><div class="t">Next contribution</div><div class="m">${esc(PO.relDate(next))} · reminder the day before</div></div><button class="btn sm" data-act="contrib-add" data-id="${c.id}">Record</button></div></div><div class="sec">Turn order</div><div class="card list">${(c.order.length?c.order:Array.from({length:c.members},(_,i)=>`Member ${i+1}`)).map((n,i)=>`<div class="row"><div class="t">${i+1}. ${esc(n)} ${i+1===c.myTurn?'<span class="pill acc">you</span>':''}</div><div class="m">${i+1<c.turn?'paid out':i+1===c.turn?'this round':'upcoming'}</div></div>`).join('')}</div><div class="sec">Your contributions</div><div class="card list">${paid.map(x=>`<div class="row"><div><div class="t">Round ${x.round}</div><div class="m">${esc(PO.relDate(x.date))}</div></div>${H.money(x.amt)}</div>`).join('')||H.empty('None recorded','')}</div>`; } };
PO.ACT['circle-edit'] = b => PO.circleForm(PO.get('circles',b.dataset.id));
PO.ACT['contrib-add'] = b => { const c=PO.get('circles',b.dataset.id); const gid=PO.group(()=>{ PO.commit('contrib',PO.uid('cb'),{circleId:c.id,date:PO.today(),amt:c.contrib,round:c.turn}); PO.commit('tx',PO.uid('t'),{kind:'expense',amt:c.contrib,cur:PO.cur(),acct:PO.profile().defaultAcct||(PO.list('accts')[0]||{}).id,cat:PO.cid(PO.state.currentProfile,'save'),payee:c.name,payeeId:PO.ensurePayee(c.name),date:PO.today(),status:'cleared',source:'circle',circleId:c.id,tags:[],splits:[],attachments:[]},'create'); PO.commit('circles',c.id,{turn:c.turn+1},'round'); }); H.afterWrite('Contribution recorded; round advanced', gid); };

/* ---------- insights: range, compare, drill-down */
PO.SCREENS.insights = { render:(pr)=>{ const range=pr.range||'period'; const cur=PO.curPeriod(); let p, label; if(range==='period'){ p=H.periodFromParams(pr); label=PO.periodLabel(p); } else if(range==='last'){ p=PO.shiftPeriod(cur,-1,PO.cycle(),PO.ctx()); label=PO.periodLabel(p); } else if(range==='3'){ const s=PO.shiftPeriod(cur,-2,PO.cycle(),PO.ctx()); p={start:s.start,end:cur.end,days:PO.daysBetween(s.start,cur.end)+1,key:s.start}; label='Last 3 periods'; } else if(range==='12m'){ p={start:PO.addMonths(PO.today(),-12),end:PO.today(),days:365,key:'12m'}; label='Last 12 months'; } else if(range==='custom'){ p={start:pr.from||PO.addDays(PO.today(),-30),end:pr.to||PO.today(),key:'c'}; p.days=PO.daysBetween(p.start,p.end)+1; label=`${PO.fmtDate(p.start)} – ${PO.fmtDate(p.end)}`; } else { p=cur; label=PO.periodLabel(p); }
  const compare=pr.compare==='1'; const prev={start:PO.addDays(p.start,-(p.days)),end:PO.addDays(p.start,-1),days:p.days}; const spend=PO.catSpend(p); const byRoot={}; Object.entries(spend).forEach(([c,v])=>{ const r=PO.catRoot(c); byRoot[r]=(byRoot[r]||0)+v; }); const spendPrev=compare?PO.catSpend(prev):{}; const byRootPrev={}; Object.entries(spendPrev).forEach(([c,v])=>{ const r=PO.catRoot(c); byRootPrev[r]=(byRootPrev[r]||0)+v; }); const total=Object.values(byRoot).reduce((s,v)=>s+v,0); const totalPrev=Object.values(byRootPrev).reduce((s,v)=>s+v,0); const rows=Object.entries(byRoot).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]); const top=rows.slice(0,7); const otherV=rows.slice(7).reduce((s,[,v])=>s+v,0); if(otherV>0) top.push(['other',otherV]); const SER=['var(--s1)','var(--s2)','var(--s3)','var(--s4)','var(--s5)','var(--s6)','var(--s7)','var(--bar-muted)']; let acc=0; const R=40, C=2*Math.PI*R; const arcs=top.map(([c,v],i)=>{ const f=v/total; const seg=`<circle cx="60" cy="60" r="${R}" fill="none" stroke="${SER[i]}" stroke-width="16" stroke-dasharray="${Math.max(0,f*C-1.5)} ${C}" stroke-dashoffset="${-acc*C}" transform="rotate(-90 60 60)"><title>${esc(PO.catName(c))}: ${esc(PO.fmt(v,null,{force:true}))}</title></circle>`; acc+=f; return seg; }).join('');
  const trend=[]; let q=cur; for(let i=0;i<6;i++){ trend.unshift({p:q,v:PO.spentTotal(q),inc:PO.incomeIn(q)}); q=PO.shiftPeriod(q,-1,PO.cycle(),PO.ctx()); } const mx=Math.max(1,...trend.map(x=>Math.max(x.v,x.inc))); const income=PO.incomeIn(p); const merchants={}; PO.spendRows(p).forEach(r=>{ const n=PO.payeeName(r.tx)||'(no payee)'; merchants[n]=(merchants[n]||0)+r.amt; }); const topM=Object.entries(merchants).sort((a,b)=>b[1]-a[1]).slice(0,5); const nw=[]; for(let i=5;i>=0;i--) nw.push({d:PO.addMonths(PO.today(),-i),v:PO.netWorth(PO.addMonths(PO.today(),-i))}); const nmin=Math.min(...nw.map(x=>x.v)), nmax=Math.max(...nw.map(x=>x.v)); const pc=PO.pace(cur); const forecast=PO.safeToSpend(cur)-Math.round(PO.spentTotal(cur)/Math.max(1,pc.elapsed)*pc.left);
  return `${H.hdr(t('insights'), esc(label), `<button class="pill" data-go="transactions" ${H.p({from:p.start,to:p.end})}>All</button>`)}<div class="chips" style="margin-bottom:8px">${[['period',t('this_period')],['last',t('last_period')],['3','3 periods'],['12m','12 months'],['custom','Custom']].map(([v,l])=>`<button class="chip small" data-go="insights" ${H.p({...pr,range:v})} aria-pressed="${range===v}">${l}</button>`).join('')}<button class="chip small" data-go="insights" ${H.p({...pr,compare:compare?'0':'1'})} aria-pressed="${compare}">${t('compare')}</button>${range==='custom'?`<button class="chip small" data-act="ins-custom" ${H.p(pr)}>${esc(PO.fmtDate(p.start))} – ${esc(PO.fmtDate(p.end))}</button>`:''}</div>${range==='period'?H.periodNav(p,'insights',{range:'period'}):''}
  <div class="grid2" style="margin-bottom:12px"><div class="tile"><div class="k">${t('spent')}</div><div class="v">${esc(PO.fmt(total))}</div>${compare?`<div class="sub">${totalPrev?((total-totalPrev)/totalPrev*100).toFixed(0)+'% vs previous':'no previous data'}</div>`:''}</div><div class="tile"><div class="k">${t('income')}</div><div class="v">${esc(PO.fmt(income))}</div><div class="sub">saved ${income?Math.round((income-total)/income*100):0}%</div></div></div>
  <div class="card" style="display:flex;gap:14px;align-items:center"><svg viewBox="0 0 120 120" width="120" height="120" role="img" aria-label="Spend by category">${arcs||'<circle cx="60" cy="60" r="40" fill="none" stroke="var(--sunk)" stroke-width="16"/>'}<text x="60" y="57" text-anchor="middle" font-size="11" fill="var(--muted)">${t('spent')}</text><text x="60" y="73" text-anchor="middle" font-size="12" font-weight="700" fill="var(--ink)">${esc(PO.fmt(total,null,{compact:true}))}</text></svg><div class="legend" style="flex:1;min-width:0">${top.map(([c,v],i)=>`<div role="button" tabindex="0" data-go="transactions" ${H.p(c==='other'?{from:p.start,to:p.end}:{cat:c,from:p.start,to:p.end})}><i style="background:${SER[i]}"></i><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c==='other'?'Other':PO.catName(c))}</span><span class="v">${Math.round(v/total*100)}%${compare&&byRootPrev[c]?` <small>(${(v-byRootPrev[c])>0?'+':''}${Math.round((v-byRootPrev[c])/byRootPrev[c]*100)}%)</small>`:''}</span></div>`).join('')||'<div class="sub">No spending in this range.</div>'}</div></div>
  <div class="sec">Spend and income, last six periods</div><div class="card"><svg viewBox="0 0 320 110" width="100%" height="110" role="img" aria-label="Spend and income per period"><line x1="0" y1="86" x2="320" y2="86" stroke="var(--line)"/>${trend.map((x,i)=>{ const h=x.v/mx*64, hi=x.inc/mx*64; return `<rect x="${i*52+10}" y="${86-hi}" width="14" height="${hi}" rx="2" fill="var(--good)" fill-opacity=".35"><title>${esc(PO.t('income'))} ${esc(PO.fmt(x.inc,null,{force:true}))}</title></rect><rect x="${i*52+26}" y="${86-h}" width="18" height="${h}" rx="3" fill="${i===5?'var(--accent)':'var(--bar-muted)'}" role="button" data-go="insights" ${H.p({range:'period',period:x.p.start})}><title>${esc(PO.periodLabel(x.p))}: ${esc(PO.fmt(x.v,null,{force:true}))}</title></rect>${i>=4?`<text x="${i*52+35}" y="${86-h-4}" text-anchor="middle" font-size="9" fill="var(--ink)">${esc(PO.fmt(x.v,null,{compact:true,noSym:true}))}</text>`:''}<text x="${i*52+30}" y="100" text-anchor="middle" font-size="9" fill="var(--muted)">${esc(PO.fmtDate(x.p.start,{day:'numeric',month:'short'}))}</text>`; }).join('')}</svg><div class="sub">Green: income. Current period in colour. Tap a bar to open that period.</div></div>
  <div class="sec">${t('net_worth')}</div><div class="card"><svg viewBox="0 0 320 70" width="100%" height="70" role="img" aria-label="Net worth over six months"><polyline fill="none" stroke="var(--accent)" stroke-width="2" points="${nw.map((x,i)=>`${i/5*300+10},${60-(x.v-nmin)/Math.max(1,nmax-nmin)*50}`).join(' ')}"/><text x="310" y="12" text-anchor="end" font-size="10" fill="var(--ink)">${esc(PO.fmt(nw[5].v,null,{compact:true}))}</text></svg></div>
  <div class="sec">Top payees</div><div class="card list">${topM.map(([n,v])=>`<div class="row" role="button" tabindex="0" data-go="transactions" ${H.p({q:n,from:p.start,to:p.end})}><div class="t">${esc(n)}</div>${H.money(v)}</div>`).join('')||H.empty('No payees','')}</div>
  <div class="card"><div class="row"><div><div class="t">Forecast: end of this period</div><div class="m">At the current rate you finish with about ${esc(PO.fmt(forecast))}. Free.</div></div><span class="pill good">${t('free')}</span></div><div class="row"><div><div class="t">Weekly digest</div><div class="m">Sent ${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][PO.state.settings.digestDay]} morning in ${esc(PO.LANGS[PO.state.settings.lang])}</div></div><button class="chip small" data-act="digest-preview">Preview</button></div><div class="row"><div><div class="t">${t('export')}</div><div class="m">CSV and JSON, free</div></div><button class="chip small" data-go="data">${t('export')}</button></div></div>`; } };
PO.ACT['ins-custom'] = b => { const pr=JSON.parse(b.dataset.p||'{}'); PO.form({title:'Custom range', values:{from:pr.from||PO.addDays(PO.today(),-30), to:pr.to||PO.today()}, fields:[{k:'from',label:t('from'),type:'date'},{k:'to',label:t('to'),type:'date'}], validate:v=>v.from>v.to?{to:'End is before start'}:null, onSave:v=>PO.go('insights',{...pr,range:'custom',from:v.from,to:v.to}) }); };
PO.ACT['digest-preview'] = () => { const p=PO.curPeriod(); const spend=PO.catSpend(p); const top=Object.entries(spend).sort((a,b)=>b[1]-a[1])[0]; PO.form({title:'Weekly digest', fields:[{k:'x',label:'',type:'html',html:()=>`<div class="card" style="background:var(--sunk)"><b>Your week</b><p class="sub">Spent ${PO.fmt(PO.spentTotal(p),null,{force:true})} so far this period, ${PO.fmt(PO.safeToSpend(p),null,{force:true})} safe to spend. ${top?`Biggest category: ${PO.catName(top[0])} at ${PO.fmt(top[1],null,{force:true})}.`:''} ${PO.list('envs').filter(e=>PO.envSpent(e,p)/Math.max(1,PO.envLimit(e,p))>=0.5&&PO.envSpent(e,p)/Math.max(1,PO.envLimit(e,p))<0.8).map(e=>e.name).join(', ')||'No envelope'} passed halfway.</p></div>`}], saveLabel:t('close'), onSave:()=>{} }); };

/* ---------- alerts and watchlists */
PO.SCREENS.alerts = { render:()=>{ const s=PO.state.settings; const sw=(k,l,m,obj)=>`<div class="row"><div><div class="t">${l}</div><div class="m">${m}</div></div><button class="sw" role="switch" aria-checked="${(obj||s.alertsGlobal)[k]}" data-act="alert-toggle" data-k="${k}" data-scope="${obj?'quiet':'global'}" aria-label="${l}"></button></div>`; const log=PO.list('alertlog').sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,12);
  return `${H.hdr(t('alerts'), 'Two signals: thresholds and pace. Calm by design.', `<button class="pill acc" data-act="watch-add">+ Watch</button>`, t('home'))}<div class="card"><div class="row"><div><div class="t">OS notifications</div><div class="m">Permission: ${esc(s.notifPermission)}${typeof Notification!=='undefined'?` (browser says ${Notification.permission})`:''}. Asked only when you enable an alert.</div></div><button class="btn sm ghost" data-act="notif-permission">Request</button></div>${sw('near','Near par (80%)','One per envelope per day with amount left and days to go')}${sw('over','At par and over par','Includes the one-tap cover-from offer')}${sw('pace','Ahead of pace','15 points ahead of the calendar after day 3')}${sw('bills','Bills due in 2 days','With whether safe to spend covers them')}${sw('large','Large transactions','More than 3× the category average')}</div><div class="card">${sw('on',`Quiet hours ${s.quiet.from} to ${s.quiet.to}`,'Alerts wait until morning; never a sound unless you turn it on',s.quiet)}<div class="row"><div><div class="t">Back-off</div><div class="m">After two ignored alerts for an envelope, the rest go to the weekly digest</div></div></div><div class="row"><div><div class="t">Per envelope</div><div class="m">Set off, near only, or all on each envelope's edit sheet</div></div><button class="chip small" data-go="budgets">${t('budgets')}</button></div></div>
  <div class="sec">Watchlists</div><div class="card list">${PO.list('watch').map(w=>`<div class="row"><div><div class="t">${esc(w.name)}</div><div class="m">${w.cat?PO.catName(w.cat):w.payee?`payee contains "${esc(w.payee)}"`:w.tag?`#${esc(w.tag)}`:''} · alert at 80% of ${PO.fmt(w.limit)}</div></div><div class="menu"><button class="chip small" data-act="watch-edit" data-id="${w.id}">${t('edit')}</button></div></div>`).join('')||H.empty('No watches','Watch a payee, tag or category with its own threshold.')}</div>
  <div class="sec">Recent alerts</div><div class="card list">${log.map(a=>`<div class="row"><div style="min-width:0"><div class="t">${esc(a.title)}</div><div class="m">${esc(a.day)} · ${esc(a.delivered)}${a.ignored?' · ignored':''}</div></div>${a.ignored?'':`<button class="chip small" data-act="alert-ignore" data-id="${a.id}">${t('ignore')}</button>`}</div>`).join('')||H.empty('No alerts fired yet','')}</div>`; } };
PO.ACT['alert-toggle'] = b => { const k=b.dataset.k; if(b.dataset.scope==='quiet') PO.state.settings.quiet.on=!PO.state.settings.quiet.on; else PO.state.settings.alertsGlobal[k]=!PO.state.settings.alertsGlobal[k]; PO.save(); PO.render(); };
PO.ACT['alert-ignore'] = b => { PO.commit('alertlog',b.dataset.id,{ignored:true},'ignore'); PO.render(); };
PO.ACT['notif-permission'] = () => { PO.form({title:'Allow notifications?', intro:`${PO.BRAND} will send at most one notification per envelope per day, none between ${PO.state.settings.quiet.from} and ${PO.state.settings.quiet.to}, and never a sound unless you turn it on. The system prompt comes next.`, fields:[], saveLabel:'Continue', onSave:()=>{ if(typeof Notification!=='undefined'&&Notification.requestPermission){ Notification.requestPermission().then(p=>{ PO.state.settings.notifPermission=p; PO.save(); PO.render(); PO.toast(`System answered: ${p}`); }).catch(()=>{ PO.state.settings.notifPermission='denied'; PO.save(); PO.render(); }); } else { PO.state.settings.notifPermission='unsupported'; PO.save(); PO.render(); } } }); };
PO.watchForm = (w={}) => { const isNew=!w.id; PO.form({title:isNew?'New watch':w.name, values:{name:w.name||'', cat:w.cat||'', payee:w.payee||'', tag:w.tag||'', limit:w.limit??null}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'cat',label:t('category'),type:'select',options:[{v:'',l:'Any'},...H.catOptions('expense')]},{k:'payee',label:'Payee contains',type:'text'},{k:'tag',label:'Tag',type:'text'},{k:'limit',label:'Limit per period',type:'money',required:true}], onSave:v=>{ const gid=PO.group(()=>PO.commit('watch',w.id||PO.uid('w'),{name:v.name,cat:v.cat||null,payee:v.payee||null,tag:v.tag||null,limit:v.limit})); H.afterWrite('Saved', gid); }, onDelete:isNew?null:()=>{ const gid=PO.group(()=>PO.remove('watch',w.id)); H.afterWrite('Deleted', gid); } }); };
PO.ACT['watch-add'] = () => PO.watchForm();
PO.ACT['watch-edit'] = b => PO.watchForm(PO.get('watch',b.dataset.id));

/* ---------- settings */
PO.SCREENS.settings = { render:()=>{ const s=PO.state.settings, p=PO.profile(), pk=PO.pack(); const row=(l,m,r)=>`<div class="row"><div style="min-width:0"><div class="t">${l}</div><div class="m">${m}</div></div><div>${r}</div></div>`; const sw=(k,l,m,obj,scope)=>row(l,m,`<button class="sw" role="switch" aria-checked="${(obj||s)[k]}" data-act="set-toggle" data-k="${k}" data-scope="${scope||'settings'}" aria-label="${l}"></button>`);
  return `${H.hdr(t('settings'), `${esc(p.name)} · ${esc(pk.name)}`, '', t('home'))}
  <div class="sec">Money</div><div class="card">${row('Region pack',`${esc(pk.name)} · ${pk.cur} · ${pk.apps.slice(0,3).join(', ')}`,`<select class="inp" style="width:auto;padding:6px" data-act="set-region" aria-label="Region">${Object.values(PO.PACKS).map(x=>`<option value="${x.id}" ${x.id===p.region?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`)}${row(t('currency'),`Base currency of this book: ${p.cur} (${PO.dec(p.cur)} decimals)`,`<select class="inp" style="width:auto;padding:6px" data-act="set-cur" aria-label="Currency">${Object.keys(PO.CUR).map(c=>`<option ${c===p.cur?'selected':''}>${c}</option>`).join('')}</select>`)}${row(t('pay_cycle'),esc(PO.cycleName(PO.cycle())),`<button class="chip small" data-act="cycle-edit">Change</button>`)}${row('Number format',`Now: ${esc(new Intl.NumberFormat(PO.numLocale()).format(1234567.89))}`,`<select class="inp" style="width:auto;padding:6px" data-act="set-numbering" aria-label="Number format"><option value="auto" ${s.numbering==='auto'?'selected':''}>Follow region</option><option value="in" ${s.numbering==='in'?'selected':''}>Lakh and crore</option><option value="std" ${s.numbering==='std'?'selected':''}>Thousands</option></select>`)}${row('Week starts',['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][p.weekStart??1],`<select class="inp" style="width:auto;padding:6px" data-act="set-weekstart" aria-label="Week start"><option value="0" ${p.weekStart===0?'selected':''}>Sunday</option><option value="1" ${p.weekStart===1?'selected':''}>Monday</option><option value="6" ${p.weekStart===6?'selected':''}>Saturday</option></select>`)}${row('Fiscal year starts',esc(p.fiscal||pk.fiscal),`<input class="inp" style="width:90px;padding:6px" value="${esc(p.fiscal||pk.fiscal)}" data-act="set-fiscal" aria-label="Fiscal year start MM-DD">`)}${row('Default account',esc(PO.acctName(p.defaultAcct)||'First account'),`<select class="inp" style="width:auto;padding:6px" data-act="set-defacct" aria-label="Default account">${H.acctOptions().map(o=>`<option value="${o.v}" ${o.v===p.defaultAcct?'selected':''}>${esc(o.l)}</option>`).join('')}</select>`)}${row('Timezone',esc(p.tz),`<input class="inp" style="width:150px;padding:6px" value="${esc(p.tz)}" data-act="set-tz" aria-label="Timezone">`)}${row('Date input order','For imports with 03/04 style dates',`<select class="inp" style="width:auto;padding:6px" data-act="set-dateorder" aria-label="Date order"><option value="dmy" ${s.dateOrder!=='mdy'?'selected':''}>Day/Month</option><option value="mdy" ${s.dateOrder==='mdy'?'selected':''}>Month/Day</option></select>`)}</div>
  <div class="sec">Appearance and language</div><div class="card">${row(t('language'),'Interface language; numbers follow the setting above',`<select class="inp" style="width:auto;padding:6px" data-act="set-lang" aria-label="Language">${Object.entries(PO.LANGS).map(([k,v])=>`<option value="${k}" ${k===s.lang?'selected':''}>${esc(v)}${PO.I18N[k]?'':' (fallback to English)'}</option>`).join('')}</select>`)}${row(t('theme'),'System, light, dark, true black, high contrast',`<select class="inp" style="width:auto;padding:6px" data-act="set-theme" aria-label="Theme">${['system','light','dark','black','contrast'].map(x=>`<option ${x===s.theme?'selected':''}>${x}</option>`).join('')}</select>`)}${row('Text size','',`<select class="inp" style="width:auto;padding:6px" data-act="set-text" aria-label="Text size">${['normal','large','xl'].map(x=>`<option ${x===(s.text||'normal')?'selected':''}>${x}</option>`).join('')}</select>`)}${sw('hideAmounts','Hide amounts','Privacy mode in app switcher and over the shoulder')}</div>
  <div class="sec">Capture sources</div><div class="card">${sw('notif','Read payment notifications',`On this phone only, from ${esc(pk.apps.join(', '))}. Never SMS.`,s.capture,'capture')}${sw('voice','Voice entry','Transcribed on device; mixed languages understood',s.capture,'capture')}${sw('ocr','Receipt scanning','Photos stay on the phone; text read on device',s.capture,'capture')}${sw('email','Email receipt forwarding',`Your address: ${esc(PO.state.login.id)}-${esc(PO.state.currentProfile.slice(-4))}@in.penny.app`,s.capture,'capture')}${sw('location','Suggest payee from location','Optional, on device',s.capture,'capture')}</div>
  <div class="sec">More</div><div class="menu">${[['alerts',t('alerts')],['categories',t('categories')],['payees',t('payees')],['rules',t('rules')],['profiles',t('profiles')],['security',t('security')],['data',t('data')],['importer',t('import')],['history',t('history')],['trash',t('trash')]].map(([k,l])=>`<button class="chip small" data-go="${k}">${esc(l)}</button>`).join('')}<button class="chip small" data-sheet="plus">${t('plus')}</button></div>
  <div class="card" style="margin-top:12px"><b>What we never do</b><div class="sub">No ads. No loan or credit offers. No selling or sharing your transactions. Export is never locked. Analytics: ${s.analytics?'on (counts only)':'off'}.</div>${sw('analytics','Share anonymous usage counts','Never amounts, payees or notes')}</div>`; } };
document.addEventListener('change', ev=>{ const a=ev.target.dataset.act; if(!a||!a.startsWith('set-')) return; const v=ev.target.value; const p=PO.profile(); const s=PO.state.settings;
  if(a==='set-region'){ const pk=PO.PACKS[v]; p.region=v; p.cycle=p.cycle||pk.cycle; PO.toast(`Region pack ${pk.name}: apps, holidays, circle names and chips updated`); }
  if(a==='set-cur'){ p.cur=v; PO.toast(`Base currency ${v}. Existing transactions keep their own currency; totals convert.`); }
  if(a==='set-numbering') s.numbering=v; if(a==='set-weekstart') p.weekStart=Number(v); if(a==='set-fiscal'){ if(/^\d{2}-\d{2}$/.test(v)) p.fiscal=v; else { PO.toast('Use MM-DD, for example 04-01'); return; } } if(a==='set-defacct') p.defaultAcct=v; if(a==='set-tz') p.tz=v; if(a==='set-dateorder') s.dateOrder=v; if(a==='set-lang') s.lang=v; if(a==='set-theme') s.theme=v; if(a==='set-text') s.text=v; if(a==='set-autolock') s.autoLock=Number(v); if(a==='set-digest') s.digestDay=Number(v); if(a==='set-quiet-from') s.quiet.from=v; if(a==='set-quiet-to') s.quiet.to=v; if(a==='set-residency') s.residency=v; if(a==='set-actas'){ PO.state.actingAs=v; PO.toast(`Now acting as ${PO.memberName(v)} (${PO.role()})`); }
  PO.save(); PO.render(); });
PO.ACT['set-toggle'] = b => { const k=b.dataset.k, sc=b.dataset.scope; const o = sc==='capture'?PO.state.settings.capture:PO.state.settings; o[k]=!o[k]; if(k==='notif'&&o[k]) PO.toast('Notification access would be requested here with a plain explanation first.'); PO.save(); PO.render(); };

/* ---------- security */
PO.SCREENS.security = { render:()=>{ const s=PO.state.settings; return `${H.hdr(t('security'), 'App lock, encryption, duress PIN, sessions, recovery', '', t('settings'))}<div class="card"><div class="row"><div><div class="t">App lock with PIN${s.lockPin?' · on':' · off'}</div><div class="m">${s.lockPin?'Data on this device is encrypted (AES-GCM, key from your PIN via PBKDF2). Biometrics unlock a session; the PIN decrypts after a restart.':'Set a PIN to encrypt data at rest on this device.'}</div></div><button class="btn sm ${s.lockPin?'ghost':''}" data-act="pin-set">${s.lockPin?'Change':'Set PIN'}</button></div>${s.lockPin?`<div class="row"><div><div class="t">Auto-lock after</div><div class="m">Seconds of inactivity</div></div><select class="inp" style="width:auto;padding:6px" data-act="set-autolock" aria-label="Auto-lock"><option value="30" ${s.autoLock===30?'selected':''}>30</option><option value="60" ${s.autoLock===60?'selected':''}>60</option><option value="300" ${s.autoLock===300?'selected':''}>300</option><option value="0" ${s.autoLock===0?'selected':''}>Never</option></select></div><div class="row"><div><div class="t">Lock now</div></div><button class="chip small" data-act="lock-now">Lock</button></div><div class="row"><div><div class="t">Remove PIN</div><div class="m">Stores data unencrypted on this device again</div></div><button class="chip small" data-act="pin-remove">Remove</button></div>`:''}</div>
  <div class="card"><div class="row"><div><div class="t">Duress PIN${s.duressPin?' · set':''}</div><div class="m">A second PIN that opens a decoy book with plausible sample data. Your real book stays locked.</div></div><button class="btn sm ghost" data-act="duress-set" ${s.lockPin?'':'disabled'}>${s.duressPin?'Change':'Set'}</button></div><div class="row"><div><div class="t">Recovery kit</div><div class="m">${s.recoveryShown?'Shown once. If you lost it, export now and set a new PIN.':'12 words that can restore access if you forget the PIN. Shown once.'}</div></div><button class="chip small" data-act="recovery-show">${s.recoveryShown?'Regenerate':'Show'}</button></div><div class="row"><div><div class="t">Block screenshots</div><div class="m">Android FLAG_SECURE; simulated here</div></div><button class="sw" role="switch" aria-checked="${!s.screenshots}" data-act="set-toggle" data-k="screenshots" aria-label="Block screenshots"></button></div></div>
  <div class="sec">${t('devices')} and sessions</div><div class="card list">${s.devices.map(d=>`<div class="row"><div><div class="t">${esc(d.name)} ${d.current?'<span class="pill good">this device</span>':''}</div><div class="m">Last active ${esc(d.last)}</div></div>${d.current?'':`<button class="chip small" data-act="device-signout" data-id="${d.id}">Sign out</button>`}</div>`).join('')}<div class="row"><div><div class="t">New-device sign-in alerts</div><div class="m">Always on</div></div></div></div>
  <div class="sec">Encryption and residency</div><div class="card"><div class="row"><div><div class="t">Sync</div><div class="m">End-to-end encrypted relay (simulated in this prototype; data stays in this browser)</div></div><span class="pill">local</span></div><div class="row"><div><div class="t">Data residency</div><div class="m">Where the encrypted relay would store blobs</div></div><select class="inp" style="width:auto;padding:6px" data-act="set-residency" aria-label="Residency">${['auto','eu','us','in','sg'].map(x=>`<option ${x===s.residency?'selected':''}>${x}</option>`).join('')}</select></div></div>`; } };
PO.ACT['pin-set'] = () => PO.form({title:PO.state.settings.lockPin?'Change PIN':'Set a PIN', intro:'4 to 8 digits. Data on this device will be encrypted with a key derived from it. Write down the recovery kit afterwards.', fields:[{k:'a',label:'New PIN',type:'password',autofocus:true,required:true,validate:v=>/^\d{4,8}$/.test(v)?null:'4 to 8 digits'},{k:'b',label:'Repeat PIN',type:'password',required:true}], validate:v=>v.a!==v.b?{b:'PINs do not match'}:null, onSave:async v=>{ await PO.setPin(v.a); PO.ui.sessionPin=v.a; PO.render(); PO.toast('PIN set. Data is now encrypted on this device.'); } });
PO.ACT['pin-remove'] = () => PO.confirmSheet('Remove the PIN?', 'Data on this device will be stored unencrypted again.', async ()=>{ await PO.setPin(null); PO.ui.sessionPin=null; PO.render(); PO.toast('PIN removed'); });
PO.ACT['lock-now'] = () => PO.lockNow();
PO.ACT['duress-set'] = () => PO.form({title:'Duress PIN', intro:'Entering this PIN on the lock screen opens a decoy book. Make it different from your real PIN.', fields:[{k:'a',label:'Duress PIN',type:'password',autofocus:true,required:true,validate:v=>/^\d{4,8}$/.test(v)?null:'4 to 8 digits'}], validate:v=>v.a===PO.ui.sessionPin?{a:'Must differ from your real PIN'}:null, onSave:async v=>{ await PO.setDuress(v.a); PO.render(); PO.toast('Duress PIN set. Lock and try it.'); }, onDelete:PO.state.settings.duressPin?async()=>{ await PO.setDuress(null); PO.render(); PO.toast('Duress PIN removed'); }:null, deleteLabel:'Remove' });
PO.ACT['recovery-show'] = () => { const words='anchor basket candle dawn ember fabric garden harbor island jasmine kettle lantern meadow needle orbit pepper quartz ribbon saddle timber umbrella velvet walnut yonder'.split(' '); const kit=Array.from({length:12},(_,i)=>words[(i*7+PO.state.seq+i*i)%words.length]).join(' '); PO.state.settings.recoveryShown=true; PO.save(); PO.form({title:'Recovery kit', intro:'Write these 12 words down and keep them offline. They are shown once. Without the PIN or this kit, encrypted data cannot be recovered; we cannot reset it for you.', fields:[{k:'kit',label:'Your words',type:'readonly'}], values:{kit}, saveLabel:'I have written them down', onSave:()=>{ PO.render(); } }); };
PO.ACT['device-signout'] = b => { PO.state.settings.devices=PO.state.settings.devices.filter(d=>d.id!==b.dataset.id); PO.save(); PO.render(); PO.toast('Device signed out; its keys are revoked'); };

/* ---------- data: export, import, backup, restore, delete */
PO.SCREENS.data = { render:()=>{ const b=PO.backups(); const size=JSON.stringify(PO.state).length; return `${H.hdr(t('data'), `${PO.list('tx').length} transactions · ${(size/1024).toFixed(0)} KB · ${PO.saveState==='error'?'storage blocked in this browser':'saved locally'}`, '', t('settings'))}
  <div class="card"><div class="row"><div><div class="t">${t('export')} JSON (everything)</div><div class="m">Full book, schema 1, re-importable</div></div><button class="btn sm" data-act="export-json">${t('export')}</button></div><div class="row"><div><div class="t">${t('export')} CSV (transactions)</div><div class="m">Opens in any spreadsheet</div></div><button class="btn sm ghost" data-act="export-csv">${t('export')}</button></div><div class="row"><div><div class="t">${t('import')}</div><div class="m">Penny JSON, or CSV/OFX from 12 other apps with a column mapper</div></div><button class="btn sm ghost" data-go="importer">${t('import')}</button></div></div>
  <div class="sec">${t('backup')}</div><div class="card"><div class="row"><div><div class="t">Back up now</div><div class="m">Encrypted snapshot to your own cloud folder (simulated as a local snapshot). Keeps 5.</div></div><button class="btn sm" data-act="backup-now">Back up</button></div>${b.map(x=>`<div class="row"><div><div class="t">${esc(x.label)}</div><div class="m">${esc(new Date(x.ts).toLocaleString())} · ${(x.size/1024).toFixed(0)} KB</div></div><button class="chip small" data-act="backup-restore" data-i="${x.i}">${t('restore')}</button></div>`).join('')||'<div class="sub">No backups yet.</div>'}</div>
  <div class="sec">Danger zone</div><div class="card"><div class="row"><div><div class="t">Delete this book (${esc(PO.profile().name)})</div><div class="m">All its data goes to Trash for 30 days, then is purged</div></div><button class="btn sm danger" data-act="profile-delete">${t('delete')}</button></div><div class="row"><div><div class="t">Delete everything</div><div class="m">Wipes this device and (in the real app) the relay within 24 hours. Export first.</div></div><button class="btn sm danger" data-act="wipe-all">Delete all</button></div></div>`; } };
PO.ACT['export-json'] = () => PO.form({title:'JSON export', intro:'Downloads are blocked inside this preview, so copy the text. In the app this saves a file or shares it.', fields:[{k:'j',label:'',type:'textarea',code:true,rows:10}], values:{j:PO.exportJSON()}, saveLabel:'Copy', onSave:v=>{ if(navigator.clipboard) navigator.clipboard.writeText(v.j).then(()=>PO.toast('Copied')).catch(()=>PO.toast('Select the text to copy')); return false; } });
PO.ACT['export-csv'] = () => PO.form({title:'CSV export', fields:[{k:'c',label:'',type:'textarea',code:true,rows:10}], values:{c:PO.exportCSV()}, saveLabel:'Copy', onSave:v=>{ if(navigator.clipboard) navigator.clipboard.writeText(v.c).then(()=>PO.toast('Copied')).catch(()=>PO.toast('Select the text to copy')); return false; } });
PO.ACT['backup-now'] = () => { const ok=PO.backup('Manual'); PO.render(); PO.toast(ok?'Backup saved':'Backup failed: storage is full or blocked'); };
PO.ACT['backup-restore'] = b => PO.confirmSheet('Restore this backup?', 'Current data is replaced. A safety backup of the current state is taken first.', ()=>{ PO.backup('Before restore'); PO.restoreBackup(Number(b.dataset.i)); PO.afterLoad(); PO.go('home'); PO.toast('Restored'); });
PO.ACT['profile-delete'] = () => { const p=PO.profile(); const others=Object.values(PO.state.profiles).filter(x=>x.id!==p.id&&!x.deleted_at); if(!others.length){ PO.toast('You need at least one book'); return; } PO.confirmSheet(`Delete ${p.name}?`, 'Everything in this book goes to Trash for 30 days.', ()=>{ const gid=PO.group(()=>PO.ENT.forEach(e=>PO.list(e).forEach(x=>PO.remove(e,x.id)))); p.deleted_at=new Date().toISOString(); PO.state.currentProfile=others[0].id; PO.save(); PO.go('home'); PO.toast(`${p.name} deleted`, gid); }, t('delete'), p.name); };
PO.ACT['wipe-all'] = () => PO.confirmSheet('Delete everything?', 'This cannot be undone. Export first if you want a copy.', ()=>{ PO.wipeAll(); PO._key=null; PO.state=PO.seed('IN'); PO.state.settings.onboarded=false; PO.saveNow(); PO.go('onboarding',{},{replace:true}); PO.toast('Everything deleted'); }, 'Delete all', 'DELETE');

/* ---------- importer */
PO.SCREENS.importer = { render:(pr)=>{ const st=PO.ui.imp||(PO.ui.imp={step:1}); if(st.step===1) return `${H.hdr(t('import'), 'Paste CSV from any bank or app. Presets for YNAB, Monarch, Mint, Money Manager, Splitwise, Bluecoins and more.', '', t('data'))}<div class="card"><div class="field"><label for="imp-text">CSV text (or a Penny JSON export)</label><textarea id="imp-text" class="inp code" rows="8" placeholder="Date,Payee,Category,Outflow,Inflow&#10;2026-11-01,Zomato,Eating out,340,"></textarea></div><div class="field"><label for="imp-file">Or choose a file</label><input id="imp-file" type="file" accept=".csv,.txt,.json,.ofx,.qif"></div><div class="field"><label for="imp-acct">Into account</label><select id="imp-acct" class="inp">${H.acctOptions().map(o=>`<option value="${o.v}">${esc(o.l)}</option>`).join('')}</select></div><button class="btn" data-act="imp-parse">Parse</button><button class="chip small" style="margin-top:8px" data-act="imp-sample">Use a sample YNAB file</button></div>${st.error?H.err('Could not read that file', st.error, `<button class="btn sm ghost" data-act="imp-reset">Try again</button>`):''}`;
  if(st.step===2) return `${H.hdr('Map columns', `${st.preset.name} preset · ${st.rows.length} rows`, '', t('import'))}<div class="card"><div class="map">${['date','payee','amt','out','in','cat','acct','note','cur','kind'].map(k=>`<label for="map-${k}">${k}</label><select id="map-${k}" class="inp" data-map="${k}"><option value="">—</option>${st.headers.map(h=>`<option ${st.map[k]===h?'selected':''}>${esc(h)}</option>`).join('')}</select>`).join('')}</div><div class="sub" style="margin-top:8px">Use either a single amount column, or separate out and in columns.</div><div style="display:flex;gap:8px;margin-top:10px"><button class="btn" style="flex:1" data-act="imp-preview">Preview</button><button class="btn sm ghost" data-act="imp-reset">Back</button></div></div>`;
  if(st.step===3){ const ok=st.drafts.filter(d=>!d.errors.length), bad=st.drafts.filter(d=>d.errors.length), dup=ok.filter(d=>d.dupe); return `${H.hdr('Preview', `${ok.length} ready · ${dup.length} possible duplicates · ${bad.length} with errors`, '', t('import'))}${st.loading?H.loading():''}<div class="card" style="overflow-x:auto"><table class="prev"><tr><th>Line</th><th>Date</th><th>Payee</th><th>Category</th><th>Amount</th><th></th></tr>${st.drafts.slice(0,30).map(d=>`<tr style="${d.errors.length?'color:var(--danger)':''}"><td>${d.line}</td><td>${esc(d.date)}</td><td>${esc(d.payee)}</td><td>${esc(PO.catName(d.cat))}</td><td>${esc(PO.fmt((d.kind==='income'?1:-1)*d.amt,d.cur,{force:true}))}</td><td>${d.errors.join(', ')}${d.dupe?'dupe':''}</td></tr>`).join('')}</table>${st.drafts.length>30?`<div class="sub">…and ${st.drafts.length-30} more</div>`:''}</div><div class="card"><div class="row"><div><div class="t">Skip possible duplicates</div></div><button class="sw" role="switch" aria-checked="${st.skipDupes!==false}" data-act="imp-toggle-dupes" aria-label="Skip duplicates"></button></div></div><div style="display:flex;gap:8px"><button class="btn" style="flex:1" data-act="imp-commit">Import ${ok.length-(st.skipDupes!==false?dup.length:0)}</button><button class="btn sm ghost" data-act="imp-back">Back</button></div>`; } return ''; },
  after:()=>{ const f=$('#imp-file'); if(f) f.addEventListener('change', ev=>{ const file=ev.target.files[0]; if(!file) return; const r=new FileReader(); r.onload=()=>{ $('#imp-text').value=r.result; }; r.onerror=()=>{ PO.ui.imp.error='The file could not be read.'; PO.render(); }; r.readAsText(file); }); } };
PO.ACT['imp-sample'] = () => { $('#imp-text').value=`Account,Flag,Date,Payee,Category Group/Category,Category Group,Category,Memo,Outflow,Inflow,Cleared\nChecking,,${PO.addDays(PO.today(),-2)},Starbucks,Food: Eating out,Food,Eating out,,6.40,0.00,Cleared\nChecking,,${PO.addDays(PO.today(),-3)},Employer,Inflow: Ready to Assign,Inflow,Ready to Assign,Salary,0.00,2500.00,Cleared\nChecking,,${PO.addDays(PO.today(),-4)},Whole Foods,Food: Groceries,Food,Groceries,,84.12,0.00,Cleared\nChecking,,bad-date,Mystery,,,,,abc,,`; };
PO.ACT['imp-parse'] = () => { const text=($('#imp-text').value||'').trim(); const acct=$('#imp-acct').value; const st=PO.ui.imp; st.error=null; if(!text){ st.error='Paste some CSV or choose a file first.'; PO.render(); return; } if(text.startsWith('{')){ try{ PO.importJSON(text); PO.afterLoad(); PO.ui.imp=null; PO.go('home'); PO.toast('Penny export imported'); }catch(e){ st.error=e.message; PO.render(); } return; } const rows=PO.parseCSV(text); if(rows.length<2){ st.error='Need a header row and at least one data row.'; PO.render(); return; } st.headers=rows[0].map(h=>h.trim()); st.rows=rows.slice(1); st.preset=PO.detectPreset(st.headers); st.map = st.preset.name==='Generic' ? PO.guessMap(st.headers) : {...PO.guessMap(st.headers), ...Object.fromEntries(Object.entries(st.preset.map).filter(([,h])=>st.headers.includes(h)))}; st.acct=acct; st.step=2; PO.render(); };
PO.ACT['imp-preview'] = () => { const st=PO.ui.imp; document.querySelectorAll('[data-map]').forEach(s=>{ st.map[s.dataset.map]=s.value; }); if(!st.map.date||!(st.map.amt||st.map.out||st.map.in)){ PO.toast('Map at least a date and an amount column'); return; } st.loading=true; st.step=3; st.drafts=[]; PO.render(); setTimeout(()=>{ st.drafts=PO.mapRows(st.rows, st.map, st.headers, st.acct); st.loading=false; PO.render(); }, 300); };
PO.ACT['imp-toggle-dupes'] = () => { PO.ui.imp.skipDupes = PO.ui.imp.skipDupes===false ? true : false; PO.render(); };
PO.ACT['imp-back'] = () => { PO.ui.imp.step=2; PO.render(); };
PO.ACT['imp-reset'] = () => { PO.ui.imp={step:1}; PO.render(); };
PO.ACT['imp-commit'] = () => { const st=PO.ui.imp; const list=st.drafts.filter(d=>!d.errors.length&&!(st.skipDupes!==false&&d.dupe)); const gid=PO.group(()=>list.forEach(d=>{ const payeeId=PO.ensurePayee(d.payee); const {patch}=PO.applyRules({...d,payeeId}); PO.commit('tx',PO.uid('t'),{kind:d.kind,amt:d.amt,cur:d.cur,acct:d.acct,cat:patch.cat||d.cat,payeeId,payee:d.payee,date:d.date,note:d.note,status:'cleared',source:'import',tags:patch.tags||[],splits:[],attachments:[]},'import'); })); PO.ui.imp=null; PO.go('transactions',{}); PO.toast(`Imported ${list.length} transactions`, gid); };

/* ---------- profiles and spaces: login, books, members, roles, invites, audit, act-as */
PO.SCREENS.profiles = { render:()=>{ const s=PO.state; const profs=Object.values(s.profiles).filter(p=>!p.deleted_at); const p=PO.profile(); const space=p.kind==='space'; const invites=PO.list('invites').filter(i=>i.status==='pending');
  return `${H.hdr(t('profiles'), `Signed in as ${esc(s.login.name)} · ${esc(s.login.email)}`, `<button class="pill acc" data-act="profile-add">+ Book or space</button>`, t('home'))}
  <div class="card"><div class="sub">Books (separate ledgers) and shared spaces</div>${profs.map(x=>`<div class="row ${x.id===s.currentProfile?'sel':''}" role="button" tabindex="0" data-act="profile-switch" data-id="${x.id}"><div style="min-width:0"><div class="t">${esc(x.name)} <span class="pill">${esc(x.kind)}</span>${x.supervisorId?'<span class="pill">supervised</span>':''}</div><div class="m">${esc(PO.PACKS[x.region]?.name||x.region)} · ${esc(x.cur)} · ${x.kind==='space'?`${(x.members||[]).length} members`:esc(PO.cycleName(x.cycle||PO.PACKS[x.region].cycle))}</div></div><div class="menu">${x.id===s.currentProfile?`<button class="chip small" data-act="profile-edit" data-id="${x.id}">${t('edit')}</button>`:`<span class="pill acc">${t('switch')}</span>`}</div></div>`).join('')}</div>
  ${space?`<div class="sec">${t('members')} · acting as ${esc(PO.memberName(s.actingAs))} (${esc(PO.role())})</div><div class="card list">${(p.members||[]).map(m=>`<div class="row"><div style="min-width:0"><div class="t">${esc(m.name)} ${m.id===s.login.id?'<span class="pill good">you</span>':''}</div><div class="m">${esc(m.email||'no login yet')} · ${esc(m.role)}${Object.keys(m.overrides||{}).length?` · ${Object.entries(m.overrides).map(([e,r])=>`${PO.get('envs',e)?.name||'envelope'}: ${r}`).join(', ')}`:''}</div></div><div class="menu">${PO.can('manage')&&m.id!==s.login.id?`<button class="chip small" data-act="member-role" data-id="${m.id}">${t('role')}</button><button class="chip small" data-act="member-override" data-id="${m.id}">Per envelope</button><button class="chip small" data-act="member-remove" data-id="${m.id}">Remove</button>`:''}${m.id===s.login.id&&p.members.find(x=>x.id===s.login.id)?.role!=='owner'?`<button class="chip small" data-act="member-leave">Leave</button>`:''}${m.id===s.login.id&&m.role==='owner'?`<button class="chip small" data-act="owner-transfer">Transfer ownership</button>`:''}</div></div>`).join('')}<div class="row"><div><div class="t">Act as (demo of permissions)</div><div class="m">See the space as another member would</div></div><select class="inp" style="width:auto;padding:6px" data-act="set-actas" aria-label="Act as">${(p.members||[]).map(m=>`<option value="${m.id}" ${m.id===s.actingAs?'selected':''}>${esc(m.name)} · ${m.role}</option>`).join('')}</select></div></div>
  <div class="sec">${t('invite')}</div><div class="card list">${invites.map(i=>`<div class="row"><div style="min-width:0"><div class="t">${esc(i.email)} · ${esc(i.role)}</div><div class="m">Expires ${esc(PO.fmtDate(i.expires))} · link …${esc(i.token.slice(-6))}</div></div><div class="menu"><button class="chip small" data-act="invite-copy" data-token="${esc(i.token)}">Copy link</button><button class="chip small" data-act="invite-accept" data-id="${i.id}">Simulate accept</button><button class="chip small" data-act="invite-revoke" data-id="${i.id}">Revoke</button></div></div>`).join('')||'<div class="sub">No pending invitations.</div>'}${PO.can('manage')?`<div style="margin-top:8px"><button class="btn sm" data-act="member-invite">${t('invite')} by email, phone, link or QR</button></div>`:''}</div>
  <div class="sec">${t('audit')}</div><div class="card list">${(p.audit||[]).slice(0,10).map(a=>`<div class="row"><div style="min-width:0"><div class="t">${esc(a.text)}</div><div class="m">${esc(a.actor)} · ${esc(new Date(a.ts).toLocaleString())}</div></div></div>`).join('')||'<div class="sub">No entries yet.</div>'}</div>
  <div class="sec">Advisor links</div><div class="card"><div class="row"><div><div class="t">Read-only report link</div><div class="m">Time-limited, revocable, watermarked; no login needed</div></div><button class="chip small" data-act="advisor-link">Create</button></div>${(p.advisorLinks||[]).map(l=>`<div class="row"><div><div class="t">…${esc(l.token.slice(-8))}</div><div class="m">Expires ${esc(PO.fmtDate(l.expires))}</div></div><button class="chip small" data-act="advisor-revoke" data-token="${esc(l.token)}">Revoke</button></div>`).join('')}</div>`:''}
  <div class="sec">Login</div><div class="card"><div class="row"><div><div class="t">Sign-in methods</div><div class="m">Passkey · Email code · Phone OTP · Apple · Google · Local-only mode</div></div><button class="chip small" data-act="login-edit">${t('edit')}</button></div><div class="row"><div><div class="t">Second account on this device</div><div class="m">Work and personal, each with own keys</div></div><button class="chip small" data-act="toast-msg" data-msg="Would open the sign-in flow for a second account">Add</button></div></div>`; } };
PO.ACT['toast-msg'] = b => PO.toast(b.dataset.msg);
PO.ACT['profile-switch'] = b => { const id=b.dataset.id; if(id===PO.state.currentProfile){ return; } PO.state.currentProfile=id; PO.state.actingAs=PO.state.login.id; PO.save(); PO.afterLoad(); PO.go('home'); PO.toast(`Switched to ${PO.profile().name}`); };
PO.ACT['profile-add'] = () => PO.form({title:'New book or space', values:{kind:'personal', region:PO.profile().region}, fields:[{k:'name',label:'Name',type:'text',required:true,autofocus:true},{k:'kind',label:'Type',type:'chips',options:[{v:'personal',l:'Personal book'},{v:'business',l:'Business book'},{v:'supervised',l:'Supervised (child)'},{v:'space',l:'Shared space'}]},{k:'region',label:'Region',type:'select',options:Object.values(PO.PACKS).map(p=>({v:p.id,l:`${p.name} · ${p.cur}`}))}], onSave:v=>{ const members = v.kind==='space'?[{id:PO.state.login.id,name:'You',email:PO.state.login.email,role:'owner',overrides:{}}]:[]; const p=PO.createProfile({name:v.name,kind:v.kind,region:v.region,members,supervisorId:v.kind==='supervised'?PO.state.login.id:null}); PO.state.currentProfile=p.id; PO.save(); PO.go('home'); PO.toast(`${p.name} created`); } });
PO.ACT['profile-edit'] = b => { const p=PO.state.profiles[b.dataset.id]; PO.form({title:p.name, values:{name:p.name, kind:p.kind}, fields:[{k:'name',label:'Name',type:'text',required:true},{k:'kind',label:'Type',type:'select',options:[{v:'personal',l:'Personal'},{v:'business',l:'Business'},{v:'supervised',l:'Supervised'},{v:'space',l:'Shared space'}]}], onSave:v=>{ p.name=v.name; if(v.kind!==p.kind){ p.kind=v.kind; if(v.kind==='space'&&!(p.members||[]).length) p.members=[{id:PO.state.login.id,name:'You',email:PO.state.login.email,role:'owner',overrides:{}}]; } PO.save(); PO.render(); PO.toast('Saved'); } }); };
PO.ACT['member-invite'] = () => PO.form({title:t('invite'), fields:[{k:'to',label:'Email or phone',type:'text',required:true,autofocus:true},{k:'role',label:t('role'),type:'select',options:['admin','editor','contributor','viewer'].map(r=>({v:r,l:r}))},{k:'x',label:'',type:'html',html:()=>`<div class="sub">The invitee sees what will be shared before accepting. Link expires in 7 days and can be revoked. Roles: admin manages members; editor edits anything; contributor adds and edits own; viewer reads.</div>`}], saveLabel:'Send invite', onSave:v=>{ PO.commit('invites',PO.uid('inv'),{email:v.to,role:v.role,token:PO.uid('tok'),expires:PO.addDays(PO.today(),7),status:'pending'}); PO.audit(`Invited ${v.to} as ${v.role}`); PO.render(); PO.toast('Invitation created. Copy the link to share it.'); } });
PO.ACT['invite-copy'] = b => { const link=`https://penny.app/join/${b.dataset.token}`; if(navigator.clipboard) navigator.clipboard.writeText(link).then(()=>PO.toast('Link copied')).catch(()=>PO.toast(link)); else PO.toast(link); };
PO.ACT['invite-accept'] = b => { const i=PO.get('invites',b.dataset.id); const p=PO.profile(); p.members.push({id:PO.uid('m'),name:i.email.split('@')[0],email:i.email,role:i.role,overrides:{}}); PO.commit('invites',i.id,{status:'accepted'},'accept'); PO.audit(`${i.email} joined as ${i.role}`); PO.save(); PO.render(); PO.toast('Member joined'); };
PO.ACT['invite-revoke'] = b => { PO.commit('invites',b.dataset.id,{status:'revoked'},'revoke'); PO.audit('Revoked an invitation'); PO.render(); };
PO.ACT['member-role'] = b => { const p=PO.profile(); const m=p.members.find(x=>x.id===b.dataset.id); PO.form({title:`${t('role')} for ${m.name}`, values:{role:m.role}, fields:[{k:'role',label:t('role'),type:'chips',options:['admin','editor','contributor','viewer'].map(r=>({v:r,l:r}))}], onSave:v=>{ const old=m.role; m.role=v.role; PO.audit(`Changed ${m.name} from ${old} to ${v.role}`); PO.save(); PO.render(); PO.toast('Role updated'); } }); };
PO.ACT['member-override'] = b => { const p=PO.profile(); const m=p.members.find(x=>x.id===b.dataset.id); const envs=PO.list('envs'); PO.form({title:`Per-envelope access for ${m.name}`, values:Object.fromEntries(envs.map(e=>[e.id,(m.overrides||{})[e.id]||''])), fields:envs.map(e=>({k:e.id,label:e.name,type:'select',options:[{v:'',l:`Default (${m.role})`},{v:'none',l:'No access'},{v:'viewer',l:'View'},{v:'contributor',l:'Add own'},{v:'editor',l:'Edit all'}]})), onSave:v=>{ m.overrides={}; Object.entries(v).forEach(([k,r])=>{ if(r) m.overrides[k]=r; }); PO.audit(`Changed per-envelope access for ${m.name}`); PO.save(); PO.render(); PO.toast('Saved'); } }); };
PO.ACT['member-remove'] = b => { const p=PO.profile(); const m=p.members.find(x=>x.id===b.dataset.id); PO.confirmSheet(`Remove ${m.name}?`, 'Their past transactions stay, labelled ex-member. Private details are scrubbed on request.', ()=>{ p.members=p.members.filter(x=>x.id!==m.id); if(PO.state.actingAs===m.id) PO.state.actingAs=PO.state.login.id; PO.audit(`Removed ${m.name}`); PO.save(); PO.render(); PO.toast('Removed'); }); };
PO.ACT['member-leave'] = () => { const p=PO.profile(); PO.confirmSheet(`Leave ${p.name}?`, 'You lose access; your entries stay for the others.', ()=>{ p.members=p.members.filter(x=>x.id!==PO.state.login.id); const other=Object.values(PO.state.profiles).find(x=>x.id!==p.id&&!x.deleted_at); PO.state.currentProfile=other.id; PO.save(); PO.go('home'); PO.toast('You left the space'); }); };
PO.ACT['owner-transfer'] = () => { const p=PO.profile(); const others=p.members.filter(m=>m.id!==PO.state.login.id); PO.form({title:'Transfer ownership', fields:[{k:'to',label:'New owner',type:'select',options:others.map(m=>({v:m.id,l:m.name})),required:true}], saveLabel:'Transfer', onSave:v=>{ p.members.forEach(m=>{ if(m.id===v.to) m.role='owner'; else if(m.id===PO.state.login.id) m.role='admin'; }); PO.audit(`Transferred ownership to ${PO.memberName(v.to)}`); PO.save(); PO.render(); PO.toast('Ownership transferred; you are now admin'); } }); };
PO.ACT['advisor-link'] = () => { const p=PO.profile(); p.advisorLinks=p.advisorLinks||[]; const token=PO.uid('adv'); p.advisorLinks.push({token,expires:PO.addDays(PO.today(),30)}); PO.audit('Created an advisor link'); PO.save(); PO.render(); PO.toast('Read-only link created for 30 days'); };
PO.ACT['advisor-revoke'] = b => { const p=PO.profile(); p.advisorLinks=(p.advisorLinks||[]).filter(l=>l.token!==b.dataset.token); PO.save(); PO.render(); };
PO.ACT['login-edit'] = () => PO.form({title:'Your login', values:{name:PO.state.login.name, email:PO.state.login.email}, fields:[{k:'name',label:'Name',type:'text',required:true},{k:'email',label:'Email',type:'text',required:true,validate:v=>/@/.test(v)?null:'Enter an email'},{k:'x',label:'',type:'html',html:()=>`<div class="chips"><span class="chip small">Passkey ✓</span><span class="chip small">Email code ✓</span><span class="chip small">Phone OTP</span><span class="chip small">Apple</span><span class="chip small">Google</span></div>`}], onSave:v=>{ PO.state.login.name=v.name; PO.state.login.email=v.email; Object.values(PO.state.profiles).forEach(p=>(p.members||[]).forEach(m=>{ if(m.id===PO.state.login.id){ m.name=v.name; m.email=v.email; } })); PO.save(); PO.render(); } });

/* ---------- history and trash */
PO.SCREENS.history = { render:(pr)=>{ let evs=PO.state.events.filter(e=>e.profileId===PO.state.currentProfile); if(pr.ent) evs=evs.filter(e=>e.ent===pr.ent); if(pr.id) evs=evs.filter(e=>e.id===pr.id); evs=evs.slice().reverse().slice(0,80); const desc=e=>{ const o=e.after||e.before||{}; const name=o.name||PO.payeeName(o)||(o.cat?PO.catName(o.cat):'')||o.email||o.desc||e.id; const diff=e.before&&e.after?Object.keys(e.after).filter(k=>!['updated_at','version'].includes(k)&&JSON.stringify(e.after[k])!==JSON.stringify(e.before[k])).map(k=>`${k}: ${fmtV(e.before[k])} → ${fmtV(e.after[k])}`).join('; '):''; return {name, diff}; }; const fmtV=v=>v==null?'—':typeof v==='object'?JSON.stringify(v).slice(0,40):String(v).slice(0,40);
  return `${H.hdr(t('history'), pr.id?'One object':'Every change in this book, newest first', '', t('home'))}<div class="card list">${evs.map(e=>{ const d=desc(e); return `<div class="row"><div style="min-width:0"><div class="t">${esc(e.label)} ${esc(e.ent)} · ${esc(d.name)}</div><div class="m">${esc(e.actorName||e.actor)} · ${esc(new Date(e.ts).toLocaleString())}${d.diff?` · ${esc(d.diff)}`:''}</div></div>${e.label!=='undo'?`<button class="chip small" data-act="event-revert" data-seq="${e.seq}">Revert</button>`:''}</div>`; }).join('')||H.empty('No history yet','')}</div>`; } };
PO.ACT['event-revert'] = b => { const ev=PO.state.events.find(e=>e.seq===Number(b.dataset.seq)); if(!ev) return; const gid=PO.group(()=>PO.revertEvent(ev)); H.afterWrite('Reverted (as a new change, so it can be undone too)', gid); };
PO.SCREENS.trash = { render:()=>{ const items=[]; PO.ENT.forEach(ent=>PO.listDeleted(ent).forEach(x=>items.push({ent,x}))); items.sort((a,b)=>b.x.deleted_at.localeCompare(a.x.deleted_at)); const name=(ent,x)=>x.name||PO.payeeName(x)||(x.cat?PO.catName(x.cat):'')||x.desc||x.email||ent; const left=x=>Math.max(0,30-Math.floor((Date.now()-new Date(x.deleted_at))/864e5));
  return `${H.hdr(t('trash'), `${items.length} items · purged after 30 days`, items.length?`<button class="pill" data-act="trash-empty">Empty</button>`:'', t('home'))}<div class="card list">${items.map(({ent,x})=>`<div class="row"><div style="min-width:0"><div class="t">${esc(name(ent,x))} <span class="pill">${esc(ent)}</span></div><div class="m">${x.amt?PO.fmt(x.amt,x.cur)+' · ':''}deleted ${esc(new Date(x.deleted_at).toLocaleDateString())} · ${left(x)} days left</div></div><div class="menu"><button class="chip small" data-act="trash-restore" data-ent="${ent}" data-id="${x.id}">${t('restore')}</button><button class="chip small" data-act="trash-purge" data-ent="${ent}" data-id="${x.id}">Purge</button></div></div>`).join('')||H.empty('Trash is empty','Deleted items wait here for 30 days.')}</div>`; } };
PO.ACT['trash-restore'] = b => { const gid=PO.group(()=>PO.restore(b.dataset.ent,b.dataset.id)); H.afterWrite('Restored', gid); };
PO.ACT['trash-purge'] = b => { PO.purge(b.dataset.ent,b.dataset.id); PO.render(); PO.toast('Purged'); };
PO.ACT['trash-empty'] = () => PO.confirmSheet('Empty the trash?', 'Purged items cannot be restored.', ()=>{ PO.ENT.forEach(ent=>PO.listDeleted(ent).forEach(x=>PO.purge(ent,x.id))); PO.render(); PO.toast('Trash emptied'); });

/* ---------- Plus sheet */
PO.SHEETS.plus = { label:'Penny Plus', render:(d)=>{ const pk=PO.pack(); const s=PO.state.settings; const price=pk.price; const f=m=>PO.fmt(m,pk.cur,{force:true}); return `<div style="display:flex;justify-content:space-between;align-items:center"><b>${t('plus')}</b><button class="pill" data-act="sheet-close">${t('close')}</button></div>${d.reason?`<div class="card" style="background:var(--amber-soft);margin-top:8px">${esc(d.reason)}</div>`:''}<p class="sub">Every feature in ${PO.BRAND} is free. Plus covers what costs us money per user, and keeps the app free of ads and loan offers.</p><div class="card" style="background:var(--sunk)"><div class="legend"><div>Bank auto-sync (each fetch has a provider fee)</div><div>Unlimited receipt and document storage (1 GB free)</div><div>Priority support in your language</div><div>Early access to new features</div><div>Covers your whole household or space</div></div></div>${s.plus?`<div class="card"><b>Active · ${esc(s.plus.plan)}</b><div class="sub">Since ${esc(s.plus.since)} · ${s.plus.plan==='lifetime'?'no renewal':'renews '+esc(s.plus.renews)} · store: ${esc(s.plus.store)}</div><div class="menu" style="margin-top:8px"><button class="chip small" data-act="plus-invoices">Receipts</button><button class="chip small" data-act="plus-cancel">Cancel (two taps)</button></div></div>`:`<div class="grid2"><button class="tile" data-act="plus-buy" data-plan="monthly"><div class="k">Monthly</div><div class="v">${esc(f(price.m))}</div></button><button class="tile" data-act="plus-buy" data-plan="yearly" style="outline:2px solid var(--accent)"><div class="k">Yearly · save ~40%</div><div class="v">${esc(f(price.y))}</div></button></div><div style="height:10px"></div><button class="tile" data-act="plus-buy" data-plan="lifetime" style="width:100%"><div class="k">Lifetime · ${esc(pk.festivals[0].n)} window</div><div class="v">${esc(f(price.l))}</div><div class="sub">One payment, covers your household</div></button><div style="display:flex;gap:8px;margin-top:10px"><button class="chip small" data-act="plus-restore">Restore purchase</button><button class="chip small" data-act="plus-invoices">Receipts</button></div>`}<div class="sub" style="text-align:center;margin-top:10px">Prices in ${pk.cur} for ${esc(pk.name)} · billed by the store or on the web · cancel any time · no countdown timers</div>`; } };
PO.ACT['plus-buy'] = b => { const plan=b.dataset.plan; const pk=PO.pack(); const amt=pk.price[plan==='monthly'?'m':plan==='yearly'?'y':'l']; PO.state.settings.plus={plan, since:PO.today(), renews:plan==='monthly'?PO.addMonths(PO.today(),1):plan==='yearly'?PO.addMonths(PO.today(),12):null, store:'Google Play (simulated)'}; PO.state.settings.receipts.push({date:PO.today(), plan, amt, cur:pk.cur, id:PO.uid('rcpt')}); PO.save(); PO.rerenderSheet(); PO.toast('Plus active for your household. Receipt saved.'); };
PO.ACT['plus-restore'] = () => { const r=PO.state.settings.receipts[PO.state.settings.receipts.length-1]; if(!r){ PO.toast('No previous purchase found for this account'); return; } PO.state.settings.plus={plan:r.plan, since:r.date, renews:r.plan==='lifetime'?null:PO.addMonths(r.date,r.plan==='monthly'?1:12), store:'restored'}; PO.save(); PO.rerenderSheet(); PO.toast('Purchase restored'); };
PO.ACT['plus-cancel'] = () => PO.confirmSheet('Cancel Plus?', 'Bank sync turns manual at the end of the paid period. Nothing is deleted and every other feature stays.', ()=>{ PO.state.settings.plus=null; PO.save(); PO.rerenderSheet(); PO.toast('Cancelled. Thank you for supporting Penny.'); });
PO.ACT['plus-invoices'] = () => PO.form({title:'Receipts', fields:[{k:'x',label:'',type:'html',html:()=>PO.state.settings.receipts.length?PO.state.settings.receipts.map(r=>`<div class="row"><div><div class="t">${esc(r.plan)}</div><div class="m">${esc(r.date)} · ${esc(r.id)}</div></div>${H.money(r.amt,r.cur,{force:true})}</div>`).join(''):'<div class="sub">No receipts.</div>'}], saveLabel:t('close'), onSave:()=>{} });

/* ---------- screen notes (right panel) */
PO.NOTES = {
  onboarding:{t:'Onboarding',tag:'Gaps 7, 21, 28, 29',job:'Region, language, pay cycle and first balance in under 60 seconds; every step skippable.',pts:['14 regional packs set currency decimals, number grouping, apps, holidays and circle names.','Pay cycle options include semi-monthly, biweekly with anchor and "when money lands".','Skipping keeps sane defaults; everything is changeable in Settings.']},
  home:{t:'Home',tag:'Gaps 2, 13, 19',job:'Safe-to-spend first, then alerts, review, today, net worth and next bill.',pts:['Safe to spend = income (actual plus scheduled) − upcoming bills − goal contributions − spent, on your real pay cycle.','Alerts card lists envelopes near or over par, pace warnings, bills due and consent expiries.','The eye icon toggles privacy mode. The avatar opens profiles and spaces.','Long-press + for the full form; tap for quick add with a calculator keypad.']},
  add:{t:'Quick add',tag:'Gaps 2, 12, 32, 33',job:'Three taps for a common spend, with a calculator and duplicate detection.',pts:['Type chips switch expense, income and transfer. Transfers never double count.','Keypad supports + − × ÷ and the locale decimal separator. Validation rejects zero, negatives and wrong decimals for the currency.','Duplicates within a day with the same amount and account are flagged before saving.']},
  form:{t:'Form',tag:'Gaps 1, 7, 22, 34, 36',job:'The generic form engine behind every object: inline validation, focus trap, Escape to close, attachments, dates.',pts:['Fields validate on save and announce the first error to screen readers.','Date picker with Today and Yesterday chips; period attribution follows the date.','Attachments accept camera, gallery and files; images are resized on device.','Status chips: pending, cleared, reconciled. Saving a reconciled item un-reconciles it with a warning.']},
  review:{t:'Review queue',tag:'Gaps 18, 40',job:'Captured items from notifications, email and share sheet; accept, edit-then-accept or ignore.',pts:['Edit-then-accept opens the full form prefilled.','Always-ignore a source removes all its pending items.','Share-sheet intake parses free text into an item.','Every accept teaches the rules engine.']},
  transactions:{t:'Transactions',tag:'Gaps 8, 20, 35',job:'Working search, natural-language queries, filters, saved searches, bulk edit, two-pane on tablet.',pts:['Try "coffee last month over 200" or "cash this week".','Filter sheet covers dates, account, category, tag, type, status and amount range.','Select rows for bulk category, account, tag, date, merge duplicates or delete.','Empty state when nothing matches; error state if a screen throws.']},
  budgets:{t:'Budgets',tag:'Gaps 5, 23, 37, 38',job:'Envelopes on your pay cycle with available-to-assign, rollover and period navigation.',pts:['Navigate past and future periods; the hash keeps the period so links restore context.','Available to assign = income − assigned − goal contributions.','"Same as last period" and "fund underfunded first" are one tap.','Each envelope has edit, archive, delete, per-period limit, own period and alert mode.']},
  envelope:{t:'Envelope detail',tag:'Gaps 5, 23',job:'One envelope across periods, with its transactions and a six-period trend.',pts:['Set this period\'s limit without changing the default.','Move money from another envelope; the move is logged and undoable.','Add a watch for a lower threshold.']},
  goals:{t:'Goals',tag:'Gap 15',job:'Contribute, withdraw, pause, complete, edit and delete.',pts:['Contributions and withdrawals post real transactions in the Savings category.','Projection shows whether the per-period amount reaches the target by the date.','Festival pots are created from Budgets templates, sized from last year.']},
  accounts:{t:'Accounts',tag:'Gaps 10, 11, 14, 36',job:'All account types with archive, reassignment on delete, pass-through wallets, card cycles and sync links.',pts:['Credit cards show statement, minimum due, due date and utilisation.','Wallets can pay from a bank so nothing is double counted.','Bank links show provider, consent expiry and re-consent; fetch drops items into review.']},
  account:{t:'Account detail',tag:'Gaps 14, 36',job:'Balance history, reconcile, set balance, card payment, loan what-if.',pts:['Cash reconcile posts the difference to Unrecorded cash.','Reconcile to statement locks matching items as reconciled.','Loan what-if shows months and interest saved by prepaying.']},
  categories:{t:'Categories',tag:'Gaps 6, 30',job:'Three-level tree with create, rename, move, merge, archive, reassign on delete and reset defaults.',pts:['Merge moves transactions, splits, rules and envelopes.','Delete requires a reassignment target when the category is used.','Excluded flag keeps transfers, savings and reimbursables out of spend.']},
  tags:{t:'Tags',tag:'Gap 6',job:'Rename propagates to every transaction; delete untags.',pts:[]},
  payees:{t:'Payees',tag:'Gap 31',job:'Payee entities with aliases, default category, merge and spend history.',pts:['Merging keeps aliases so future raw names still match.','Default category pre-fills quick add.']},
  rules:{t:'Rules',tag:'Gaps 18, 30',job:'Ordered rules with preview, retroactive apply, learning and conflict detection.',pts:['Corrections create draft rules after 2 and enable after 3.','Export and import rules as JSON.']},
  recurring:{t:'Bills and recurring',tag:'Gap 9',job:'Occurrences generate ahead; pay, skip, unskip, edit this or future, pause, detect subscriptions.',pts:['Paying creates the transaction and schedules the next occurrence.','Coverage check against safe to spend on each upcoming bill.','Calendar shows bill days for this month.']},
  debt:{t:'Debt planner',tag:'Gap 11',job:'Avalanche or snowball with extra payments and a plain-words outcome.',pts:[]},
  people:{t:'People',tag:'Gaps 3, 16',job:'Lending, groups, remittances and circles in one place.',pts:['Lending entries carry partial settlements, optional interest and a history.','Groups simplify debts and settle with the regional payment rail.','Remittances show true cost from fee and rate spread.']},
  person:{t:'Lending detail',tag:'Gap 16',job:'Partial settlement, settle in full, interest to date, draft reminder.',pts:[]},
  group:{t:'Group',tag:'Gap 3',job:'Balances, simplified settle-up, expenses with equal shares.',pts:[]},
  circle:{t:'Circle',tag:'Gap 3',job:'Turn order, payout date, contributions as transactions.',pts:[]},
  insights:{t:'Insights',tag:'Gap 26',job:'Date range, compare with the previous range, drill-down from any slice or bar.',pts:['Ranges: this period, last, three periods, twelve months, custom.','Compare shows change per category.','Tap a donut legend row, a bar or a payee to open the matching transactions.']},
  alerts:{t:'Alerts',tag:'Gap 19',job:'OS permission flow, global and per-envelope settings, quiet hours, watchlists, alert log with back-off.',pts:[]},
  settings:{t:'Settings',tag:'Gaps 21, 28, 29',job:'Region pack, currency, cycle, numbering, week start, fiscal year, default account, timezone, language, theme, text size, capture sources.',pts:['Pick Arabic to see RTL mirroring; pick Germany to see the comma decimal; pick Japan for zero decimals.','Strings come from a dictionary with English fallback.']},
  security:{t:'Security',tag:'Gap 24',job:'PIN with real AES-GCM encryption at rest, auto-lock, duress PIN with decoy book, recovery kit, devices.',pts:['Set a PIN, then reload the page: the data is unreadable without it.','The duress PIN opens a decoy book; the real one stays encrypted.']},
  data:{t:'Data',tag:'Gaps 4, 25',job:'Export JSON and CSV, import, backups with restore, delete a book, delete everything.',pts:['State persists in this browser; reload to confirm.','Restore takes a safety backup first.']},
  importer:{t:'Importer',tag:'Gap 25',job:'CSV with preset detection and a column mapper, preview with errors and duplicates, loading state.',pts:['Try the sample YNAB file: one row has a bad date and amount and shows as an error.']},
  profiles:{t:'Profiles and spaces',tag:'Gaps 3, 17, 39',job:'Login, books, shared spaces, members, roles, per-envelope overrides, invitations, audit log, advisor links.',pts:['Switch to "Our home" and use Act as to see what a viewer or contributor can do.','Invite, simulate accept, change role, remove, leave, transfer ownership.','Every change in a space is in the audit log.']},
  history:{t:'History',tag:'Gap 13',job:'Every change with actor, time and field-level diff; revert any.',pts:[]},
  trash:{t:'Trash',tag:'Gap 1',job:'Soft-deleted objects of every type for 30 days; restore or purge.',pts:[]},
  plus:{t:'Penny Plus',tag:'Gap 27',job:'Regional prices, monthly, yearly, lifetime, restore purchase, receipts, cancel in two taps.',pts:[]},
  splits:{t:'Split',tag:'Gap 1',job:'Split an amount across categories; remainder stays on the main category.',pts:[]},
  confirm:{t:'Confirm',tag:'',job:'Only account and book deletion ask for typed confirmation; everything else uses undo.',pts:[]}
};
})(window.PO);
